"use client"

import * as React from "react"
import NextLink from "next/link"
import { SignOutButton } from "@clerk/nextjs"
import { ArrowDown, ArrowLeft, ArrowRight, ArrowUp, Bold, Check, CircleDollarSign, CreditCard, FileText, GripVertical, Heading2, Image as ImageIcon, ImagePlus, Italic, LayoutDashboard, Link as LinkIcon, List, ListOrdered, Menu, Minus, PanelLeftClose, PanelLeftOpen, QrCode, Redo2, Search, Settings, Space, Tags, Trash2, Type, Underline, Undo2, X } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Tabs, TabsContent } from "@/components/ui/tabs"
import { isLocalAgencyDemoSession } from "@/lib/agency/demo"
import { DEFAULT_ACCENT_COLOR, normalizeAccentColor, normalizeExternalUrl } from "@/lib/agency/branding"
import type { AgencyEvent, AgencyLead, AgencyRadar, AgencySegment, AgencySession, AgencyTemplateLibraryItem, CreditMovement, CreditPack, LetterBlock, LetterBlockType, LetterLayout, LetterTemplate, MailBatch, MailItem, SenderProfile, WatchlistCompany } from "@/lib/agency/types"
import { block, defaultLetterLayout, normalizeLetterLayout, requiredBlockTypes } from "@/lib/agency/letter-layout"
import { qrSvgDataUrl } from "@/lib/agency/qr"
import { SIC_LABELS } from "@/lib/sic-codes"

type Props = { session: AgencySession; radars: AgencyRadar[]; leads: AgencyLead[]; events: AgencyEvent[]; watchlist: WatchlistCompany[]; members: Array<{ email: string; role: string }>; templates: LetterTemplate[]; templateLibrary?: AgencyTemplateLibraryItem[]; segments?: AgencySegment[]; sender: SenderProfile | null; batches: MailBatch[]; mailItems: MailItem[]; creditBalance: number; creditPacks: CreditPack[]; creditMovements: CreditMovement[]; newCompaniesLast30Days: number | null; initialView?: string; checkoutStatus?: string }
type TemplateDraft = { id?: string; name: string; subject: string; bodyHtml: string; ctaText?: string; ctaUrl?: string; signature: string; isDefault?: boolean; sourceTemplateId?: string; serviceFocus?: string[]; layout?: LetterLayout }
const errorMessage = (error: unknown) => error instanceof Error ? error.message : "Unable to complete this action."
const mergeFields = ["company_name", "company_number", "incorporation_date", "sic_codes", "location", "registered_office_address", "agency_name", "service_focus", "opt_out_reference"]
const mergeFieldLabels: Record<string, string> = { company_name: "Company name", company_number: "Company number", incorporation_date: "Incorporation date", sic_codes: "SIC codes", location: "Location", registered_office_address: "Registered address", agency_name: "Agency name", service_focus: "Services", opt_out_reference: "Opt-out reference" }
const DEFAULT_LETTER_SAMPLE = { companyName: "Example New Company Ltd", companyNumber: "12345678", incorporationDate: "23 July 2026", location: "London, EC2A 4NA", sicCodes: ["62012"] }
const replaceMergePreview = (value: string, variables: Record<string, string>) => value.replace(/\{\{\s*([a-z_]+)\s*\}\}/gi, (_, key) => variables[key] ?? mergeFieldLabels[key] ?? "")
const deliveryCopy = "Printed and posted via Frankk ConnectMail · scheduled for the next available Second Class dispatch after owner approval. Delivery times are estimates, not guaranteed."
const mailStatus = (item: MailItem) => item.submissionUnknownAt || item.providerStatus === "submission_unknown" ? "Needs review" : ({ pending_approval: "Preview ready", sending: "Preparing", submitted: "Scheduled", production: "Production", dispatched: "Dispatched", failed: "Failed / refunded", blocked: "Needs review" }[item.status] ?? item.status)

export function AgencyWorkspace({ session, radars, leads, events, watchlist, members, templates, templateLibrary = [], segments = [], sender, batches, mailItems, creditBalance, creditPacks, creditMovements, newCompaniesLast30Days, initialView = "campaigns", checkoutStatus }: Props) {
  const [notice, setNotice] = React.useState<string | null>(checkoutStatus === "success" ? "Payment received. Credits are being added to your balance." : checkoutStatus === "cancelled" ? "Checkout cancelled. Your balance was not changed." : null)
  const [customCredits, setCustomCredits] = React.useState(250)
  const [activeView, setActiveView] = React.useState(initialView)
  const [sidebarCollapsed, setSidebarCollapsed] = React.useState(false)
  const [mobileSidebarOpen, setMobileSidebarOpen] = React.useState(false)
  const demo = isLocalAgencyDemoSession(session)
  const owner = session.role === "owner"
  async function api(path: string, body?: unknown, method = "POST") { const response = await fetch(path, { method, headers: body ? { "Content-Type": "application/json" } : undefined, body: body ? JSON.stringify(body) : undefined }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.error ?? "Request failed."); return payload }
  const reload = () => location.reload()
  async function checkCampaign(radarId: string) { try { const result = await api(`/api/app/radars/${radarId}/scan`); setNotice(`Campaign checked. ${result.leads} new ${result.leads === 1 ? "company" : "companies"} found.`); reload() } catch (error) { setNotice(errorMessage(error)) } }
  async function queue(radarId: string, leadId: string) { try { await api("/api/app/mail/queue", { radarId, leadIds: [leadId] }); reload() } catch (error) { setNotice(errorMessage(error)) } }
  async function preview(batchId: string) { try { const result = await api("/api/app/mail/preview", { batchId }); window.open(result.previewUrl, "_blank", "noopener,noreferrer"); setNotice(`Frankk preview ready for ${result.recipient}. Nothing has been charged or scheduled.`); reload() } catch (error) { setNotice(errorMessage(error)) } }
  async function approve(batchId: string) { try { const result = await api("/api/app/mail/approve", { batchId }); const scheduled = result.results.filter((item: { status: string }) => item.status === "scheduled").length; const review = result.results.filter((item: { status: string }) => item.status === "submission_unknown").length; setNotice(`${scheduled} letters scheduled.${review ? ` ${review} need manual review.` : ""}`); reload() } catch (error) { setNotice(errorMessage(error)) } }
  async function buy(packId: string) { try { const result = await api("/api/app/credits/checkout", { packId }); location.assign(result.url) } catch (error) { setNotice(errorMessage(error)) } }
  async function buyCustomCredits() { try { const result = await api("/api/app/credits/checkout", { credits: customCredits }); location.assign(result.url) } catch (error) { setNotice(errorMessage(error)) } }
  async function saveTemplateDraft(draft: TemplateDraft) {
    if (demo) { setNotice("Demo preview: this template is ready to customize. Connect a D1 workspace to save it."); return draft.id }
    let id = draft.id
    if (!id && draft.sourceTemplateId) id = (await api("/api/app/templates/clone", { sourceTemplateId: draft.sourceTemplateId })).id
    const result = await api("/api/app/mail/templates", { ...draft, id, sourceTemplateId: undefined })
    return result.id as string
  }
  async function archiveTemplate(id: string) { if (demo) { setNotice("Demo preview: saved templates can be removed in a connected workspace."); return } await api("/api/app/mail/templates", { id }, "DELETE") }
  async function saveSenderProfile(input: SenderProfile) { if (demo) { setNotice("Demo preview: sender branding is shown locally. Connect a D1 workspace to save it."); return } try { await api("/api/app/mail/sender", input, "PUT"); setNotice("Brand settings saved.") } catch (error) { setNotice(errorMessage(error)) } }
  async function createRadarFromValues(values: { name: string; sicCodes: string[]; cities?: string[]; keywords?: string[]; deliveryFrequency?: "daily" | "weekly"; autoQueueLetters?: boolean; mailTemplateId?: string; templateLibraryId?: string; segmentSlug?: string; segmentSlugs?: string[]; serviceFocus?: string[]; companyAgeDays?: number; postcodePrefixes?: string[]; dailySendLimit?: number; monthlySendLimit?: number }) {
    if (demo) { setNotice(`Demo preview: ${values.name} is ready to activate. Connect a D1 workspace to persist this radar.`); return }
    try { let mailTemplateId = values.mailTemplateId; if (!mailTemplateId && values.templateLibraryId) mailTemplateId = (await api("/api/app/templates/clone", { sourceTemplateId: values.templateLibraryId })).id; await api("/api/app/radars", { ...values, mailTemplateId, templateLibraryId: undefined, eventTypes: ["company.incorporated"], approvalRequired: true }); reload() } catch (error) { setNotice(errorMessage(error)) }
  }
  const pageMeta = ({ campaigns: ["Campaigns", "Find, review and send to newly formed companies."], "sic-finder": ["SIC Finder", "Find the official activity codes for your ideal customers."], templates: ["Letter templates", "Create branded A4 letters for your campaigns."], credits: ["Credits", "Buy credits and review workspace transactions."], settings: ["Settings", "Manage your workspace and sender details."] } as Record<string, [string, string]>)[activeView]
  return <main className="min-h-screen bg-muted/40 text-foreground"><Tabs value={activeView} onValueChange={setActiveView}><div className="flex min-h-screen">
    <AgencySidebar session={session} creditBalance={creditBalance} activeView={activeView} collapsed={sidebarCollapsed} mobileOpen={mobileSidebarOpen} demo={demo} onNavigate={setActiveView} onCollapse={() => setSidebarCollapsed((value) => !value)} onMobileClose={() => setMobileSidebarOpen(false)} />
    <div className={`min-w-0 flex-1 transition-[margin] duration-200 ${sidebarCollapsed ? "md:ml-[82px]" : "md:ml-[250px]"}`}>
      <header className="sticky top-0 z-30 flex min-h-20 items-center justify-between gap-4 border-b-2 bg-background px-4 py-3 sm:px-6 lg:px-8"><div className="flex min-w-0 items-center gap-3"><Button type="button" size="icon" variant="outline" className="shrink-0 md:hidden" onClick={() => setMobileSidebarOpen(true)} aria-label="Open navigation"><Menu className="size-5" /></Button><div className="min-w-0"><h1 className="truncate text-2xl font-black">{pageMeta[0]}</h1><p className="truncate text-sm text-muted-foreground">{pageMeta[1]}</p></div></div><div className="flex shrink-0 items-center gap-2">{activeView === "campaigns" && owner ? <Button asChild size="sm"><NextLink href="/app/campaigns/new">Create campaign <ArrowRight className="ml-2 size-4" /></NextLink></Button> : null}<Button type="button" size="sm" variant="outline" onClick={() => setActiveView("credits")} aria-label={`Open credits. Current balance ${creditBalance} credits`}>{creditBalance} credits</Button></div></header>
      <div className="mx-auto w-full max-w-[1500px] p-4 sm:p-6 lg:p-8">{notice ? <div className="mb-5 border-2 bg-[hsl(var(--chart-3))] p-3 text-sm font-medium">{notice}</div> : null}
        <TabsContent value="campaigns" className="mt-0"><CampaignSummary radars={radars} leads={leads} batches={batches} mailItems={mailItems} sender={sender} newCompaniesLast30Days={newCompaniesLast30Days} onOpenSettings={() => setActiveView("settings")} /></TabsContent>
        <TabsContent value="sic-finder" className="mt-0"><SicFinder /></TabsContent>
        <TabsContent value="templates" className="mt-0"><TemplateStudio templates={templates.filter((item) => !item.isCampaignSnapshot)} templateLibrary={templateLibrary} leads={leads} sender={sender} owner={owner} onSave={saveTemplateDraft} onArchive={archiveTemplate} onSaveSender={saveSenderProfile} /></TabsContent>
        <TabsContent value="credits" className="mt-0"><div className="space-y-4"><DeliveryNotice /><Card><CardHeader><p className="text-xs font-black uppercase tracking-widest text-muted-foreground">Available balance</p><CardTitle className="text-4xl">{creditBalance} credits</CardTitle><CardDescription>1 credit prints and posts one standard single-sided letter. Confirmed provider failures are automatically refunded.</CardDescription></CardHeader></Card><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{creditPacks.map((pack) => <Card key={pack.id} className={pack.credits === 100 ? "border-[hsl(var(--chart-2))]" : ""}><CardHeader><CardTitle>{pack.credits} credits</CardTitle><CardDescription>{pack.name} · £1.50 per credit, VAT added where applicable</CardDescription></CardHeader><CardContent>{owner ? <Button className="w-full" onClick={() => buy(pack.id)}><CreditCard className="mr-2 size-4" />Buy for £{(pack.pricePence / 100).toFixed(2)}</Button> : <p className="text-sm text-muted-foreground">Only the workspace owner can purchase credits.</p>}</CardContent></Card>)}<Card><CardHeader><CardTitle>Custom credits</CardTitle><CardDescription>Choose any amount from 25 to 5,000 · £1.50 per credit</CardDescription></CardHeader><CardContent className="space-y-3"><label className="block text-sm font-bold" htmlFor="custom-credit-amount">Credit amount</label><Input id="custom-credit-amount" type="number" min={25} max={5000} step={1} value={customCredits} onChange={(event) => setCustomCredits(Math.min(5000, Math.max(25, Math.trunc(Number(event.target.value) || 25))))} />{owner ? <Button className="w-full" onClick={buyCustomCredits}><CreditCard className="mr-2 size-4" />Buy for £{(customCredits * 1.5).toFixed(2)}</Button> : <p className="text-sm text-muted-foreground">Only the workspace owner can purchase credits.</p>}<p className="text-xs text-muted-foreground">VAT added where applicable.</p></CardContent></Card></div><Card><CardHeader><CardTitle>Credit activity</CardTitle></CardHeader><CardContent>{creditMovements.length ? <div className="divide-y-2">{creditMovements.map((movement) => <div key={movement.id} className="flex items-center justify-between py-3 text-sm"><div><p className="font-bold">{creditReason(movement.reason)}</p><p className="text-xs text-muted-foreground">{new Date(movement.createdAt).toLocaleString("en-GB")}</p></div><Badge variant={movement.delta > 0 ? "default" : "outline"}>{movement.delta > 0 ? "+" : ""}{movement.delta}</Badge></div>)}</div> : <Empty text="Credit purchases and sends will appear here." />}</CardContent></Card></div></TabsContent>
        <TabsContent value="settings" className="mt-0"><WorkspaceSettings session={session} members={members} sender={sender} onSaveSender={saveSenderProfile} /></TabsContent>
      </div>
    </div>
  </div></Tabs></main>
}

const sidebarItems = [{ value: "campaigns", label: "Campaigns", icon: LayoutDashboard }, { value: "sic-finder", label: "SIC Finder", icon: Tags }, { value: "templates", label: "Letter templates", icon: FileText }, { value: "credits", label: "Credits", icon: CircleDollarSign }] as const
function SidebarLinks({ activeView, collapsed, onNavigate, onMobileClose }: { activeView: string; collapsed: boolean; onNavigate: (view: string) => void; onMobileClose?: () => void }) { return <nav className="flex flex-1 flex-col gap-1 p-3" aria-label="Workspace navigation">{sidebarItems.map(({ value, label, icon: Icon }) => <button key={value} type="button" onClick={() => { onNavigate(value); onMobileClose?.() }} aria-current={activeView === value ? "page" : undefined} className={`flex h-11 w-full items-center justify-start gap-3 border border-transparent px-3 text-sm font-medium ${activeView === value ? "border-foreground bg-[hsl(var(--chart-2))]" : "hover:bg-muted"} ${collapsed ? "justify-center px-0" : ""}`} title={collapsed ? label : undefined}><Icon className="size-5 shrink-0" />{collapsed ? <span className="sr-only">{label}</span> : <span>{label}</span>}</button>)}</nav> }
function SidebarBottom({ activeView, collapsed, demo, onNavigate, onMobileClose }: { activeView: string; collapsed: boolean; demo: boolean; onNavigate: (view: string) => void; onMobileClose?: () => void }) { return <div className="space-y-1 border-t-2 p-3"><button type="button" onClick={() => { onNavigate("settings"); onMobileClose?.() }} aria-current={activeView === "settings" ? "page" : undefined} className={`flex h-11 w-full items-center justify-start gap-3 border border-transparent px-3 text-sm font-medium ${activeView === "settings" ? "border-foreground bg-[hsl(var(--chart-2))]" : "hover:bg-muted"} ${collapsed ? "justify-center px-0" : ""}`} title={collapsed ? "Settings" : undefined}><Settings className="size-5 shrink-0" />{collapsed ? <span className="sr-only">Settings</span> : <span>Settings</span>}</button>{!demo && process.env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY ? <SignOutButton><Button variant="ghost" className={`h-11 w-full justify-start gap-3 ${collapsed ? "justify-center px-0" : ""}`}><ArrowLeft className="size-5 shrink-0" />{collapsed ? <span className="sr-only">Sign out</span> : <span>Sign out</span>}</Button></SignOutButton> : null}</div> }
function AgencySidebar({ session, creditBalance, activeView, collapsed, mobileOpen, demo, onNavigate, onCollapse, onMobileClose }: { session: AgencySession; creditBalance: number; activeView: string; collapsed: boolean; mobileOpen: boolean; demo: boolean; onNavigate: (view: string) => void; onCollapse: () => void; onMobileClose: () => void }) { return <><aside className={`fixed inset-y-0 left-0 z-40 hidden flex-col border-r-2 bg-background transition-[width] duration-200 md:flex ${collapsed ? "w-[82px]" : "w-[250px]"}`}><div className="flex h-20 items-center gap-3 border-b-2 p-3"><div className="flex size-11 shrink-0 items-center justify-center bg-foreground text-lg font-black text-background">CR</div>{collapsed ? null : <div className="min-w-0"><p className="truncate font-black">{session.workspaceName}</p><p className="text-xs text-muted-foreground">Agency Mode · {creditBalance} credits</p></div>}</div><SidebarLinks activeView={activeView} collapsed={collapsed} onNavigate={onNavigate} /><SidebarBottom activeView={activeView} collapsed={collapsed} demo={demo} onNavigate={onNavigate} /><button type="button" onClick={onCollapse} className="absolute -right-4 top-24 flex size-8 items-center justify-center rounded-full border-2 bg-background shadow-sm" aria-label={collapsed ? "Expand navigation" : "Collapse navigation"}>{collapsed ? <PanelLeftOpen className="size-4" /> : <PanelLeftClose className="size-4" />}</button></aside>{mobileOpen ? <div className="fixed inset-0 z-50 md:hidden"><button type="button" className="absolute inset-0 bg-black/45" onClick={onMobileClose} aria-label="Close navigation" /><aside className="relative flex h-full w-[280px] flex-col border-r-2 bg-background shadow-xl"><div className="flex h-20 items-center justify-between border-b-2 p-4"><div><p className="font-black">{session.workspaceName}</p><p className="text-xs text-muted-foreground">Agency Mode · {creditBalance} credits</p></div><Button type="button" size="icon" variant="ghost" onClick={onMobileClose} aria-label="Close navigation"><X className="size-5" /></Button></div><SidebarLinks activeView={activeView} collapsed={false} onNavigate={onNavigate} onMobileClose={onMobileClose} /><SidebarBottom activeView={activeView} collapsed={false} demo={demo} onNavigate={onNavigate} onMobileClose={onMobileClose} /></aside></div> : null}</> }
function WorkspaceSettings({ session, members, sender, onSaveSender }: { session: AgencySession; members: Array<{ email: string; role: string }>; sender: SenderProfile | null; onSaveSender: (sender: SenderProfile) => void }) { return <div className="grid gap-5 lg:grid-cols-[0.7fr_1.3fr]"><Card><CardHeader><CardTitle>Workspace</CardTitle><CardDescription>Your Agency Mode account and access.</CardDescription></CardHeader><CardContent className="space-y-3 text-sm"><div><p className="font-bold">Workspace name</p><p className="text-muted-foreground">{session.workspaceName}</p></div><div><p className="font-bold">Your role</p><p className="capitalize text-muted-foreground">{session.role}</p></div><div><p className="font-bold">Members</p><div className="mt-2 divide-y border">{members.map((member) => <div key={member.email} className="flex justify-between gap-3 p-2"><span className="truncate">{member.email}</span><Badge variant="outline" className="capitalize">{member.role}</Badge></div>)}</div></div></CardContent></Card><SenderSetup sender={sender} fallbackName={session.workspaceName} fallbackEmail={session.email} onSave={onSaveSender} /></div> }
function SenderSetup({ sender, fallbackName, fallbackEmail, onSave }: { sender: SenderProfile | null; fallbackName: string; fallbackEmail: string; onSave: (sender: SenderProfile) => void }) {
  const [agencyName, setAgencyName] = React.useState(sender?.agencyName ?? fallbackName); const [replyEmail, setReplyEmail] = React.useState(sender?.replyEmail ?? fallbackEmail); const [website, setWebsite] = React.useState(sender?.website ?? ""); const [logoUrl, setLogoUrl] = React.useState(sender?.logoUrl ?? ""); const [address1, setAddress1] = React.useState(sender?.address.address1 ?? ""); const [address2, setAddress2] = React.useState(sender?.address.address2 ?? ""); const [town, setTown] = React.useState(sender?.address.town ?? ""); const [county, setCounty] = React.useState(sender?.address.county ?? ""); const [postcode, setPostcode] = React.useState(sender?.address.postcode ?? ""); const [optOutText, setOptOutText] = React.useState(sender?.optOutText ?? "To stop receiving marketing by post, use the reference printed on this letter.")
  const ready = Boolean(agencyName.trim() && replyEmail.trim() && normalizeExternalUrl(website) && address1.trim() && town.trim() && postcode.trim() && optOutText.trim())
  return <Card><CardHeader><div className="flex items-start justify-between gap-3"><div><CardTitle>Sender setup</CardTitle><CardDescription>Required before a campaign can be activated. These details appear on every printed letter.</CardDescription></div><Badge variant={ready ? "default" : "outline"}>{ready ? "Complete" : "Action required"}</Badge></div></CardHeader><CardContent className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><label className="text-sm font-bold">Business / agency name<Input className="mt-1" value={agencyName} onChange={(event) => setAgencyName(event.target.value)} /></label><label className="text-sm font-bold">Reply email<Input className="mt-1" type="email" value={replyEmail} onChange={(event) => setReplyEmail(event.target.value)} /></label><label className="text-sm font-bold">Website / CTA address<Input className="mt-1" type="url" placeholder="https://youragency.co.uk" value={website} onChange={(event) => setWebsite(event.target.value)} /></label><label className="text-sm font-bold">Logo URL <span className="font-normal text-muted-foreground">(optional)</span><Input className="mt-1" type="url" value={logoUrl} onChange={(event) => setLogoUrl(event.target.value)} /></label><label className="text-sm font-bold sm:col-span-2">Address line 1<Input className="mt-1" value={address1} onChange={(event) => setAddress1(event.target.value)} /></label><label className="text-sm font-bold sm:col-span-2">Address line 2 <span className="font-normal text-muted-foreground">(optional)</span><Input className="mt-1" value={address2} onChange={(event) => setAddress2(event.target.value)} /></label><label className="text-sm font-bold">Town / city<Input className="mt-1" value={town} onChange={(event) => setTown(event.target.value)} /></label><label className="text-sm font-bold">County <span className="font-normal text-muted-foreground">(optional)</span><Input className="mt-1" value={county} onChange={(event) => setCounty(event.target.value)} /></label><label className="text-sm font-bold">UK postcode<Input className="mt-1 uppercase" value={postcode} onChange={(event) => setPostcode(event.target.value.toUpperCase())} /></label><label className="text-sm font-bold sm:col-span-2">Opt-out wording<Input className="mt-1" value={optOutText} onChange={(event) => setOptOutText(event.target.value)} /></label></div>{!ready ? <p className="text-sm font-bold text-destructive">Complete the required fields with a valid HTTPS website before activating a campaign.</p> : null}<Button disabled={!ready} onClick={() => onSave({ agencyName, replyEmail, website, logoUrl, optOutText, address: { address1, address2, town, county, postcode, country: "GB" }, accentColor: sender?.accentColor, primaryColor: sender?.primaryColor, textColor: sender?.textColor, fontFamily: sender?.fontFamily, headerAlignment: sender?.headerAlignment })}>Save sender setup</Button></CardContent></Card>
}

function Empty({ text }: { text: string }) { return <p className="border-2 border-dashed p-4 text-sm text-muted-foreground">{text}</p> }
function creditReason(reason: string) { return ({ welcome_credit: "Welcome credit", credit_purchase: "Credit purchase", mail_reservation: "Letters approved", mail_refund: "Failed send refund" } as Record<string, string>)[reason] ?? reason.replaceAll("_", " ") }
function DeliveryNotice() { return <div className="border-2 bg-muted p-3 text-sm"><p className="font-black">Printed and posted via Frankk ConnectMail</p><p className="mt-1 text-muted-foreground">Your preview is free. After owner approval, each letter uses one credit and is scheduled for the next available Second Class dispatch. Delivery times are estimates, not guaranteed.</p></div> }

const sicOptions = Object.entries(SIC_LABELS).map(([code, description]) => ({ code, description }))
const sicSuggestions = ["Accounting", "Software", "Property", "Construction", "Recruitment", "Legal", "Marketing", "Retail"]
const sicSearchAliases: Record<string, string[]> = {
  web: ["software", "internet", "information technology"],
  website: ["software", "internet"],
  developer: ["development", "programming"],
  agency: ["advertising", "marketing", "design"],
  accountant: ["accounting", "bookkeeping", "tax"],
  lawyer: ["legal", "solicitor"],
  recruitment: ["employment", "placement"],
  property: ["real estate", "letting", "estate agency"],
  ecommerce: ["retail", "internet"],
  "e-commerce": ["retail", "internet"],
}

function SicFinder() {
  const [query, setQuery] = React.useState("")
  const [selected, setSelected] = React.useState<string[]>([])
  const deferredQuery = React.useDeferredValue(query.trim().toLowerCase())
  const terms = deferredQuery.split(/\s+/).filter(Boolean)
  const results = sicOptions.filter((option) => {
    if (!terms.length) return false
    const haystack = `${option.code} ${option.description}`.toLowerCase()
    return terms.every((term) => [term, ...(sicSearchAliases[term] ?? [])].some((candidate) => haystack.includes(candidate)))
  }).slice(0, 80)

  function toggle(code: string) {
    setSelected((current) => current.includes(code) ? current.filter((item) => item !== code) : current.length >= 20 ? current : [...current, code])
  }

  return <div className="grid gap-5 xl:grid-cols-[minmax(0,1.25fr)_minmax(320px,0.75fr)]">
    <Card>
      <CardHeader><CardTitle>Find the right SIC codes</CardTitle><CardDescription>Search the official UK Standard Industrial Classification list by activity or code. Choose the activities your ideal customers are likely to register under.</CardDescription></CardHeader>
      <CardContent className="space-y-4">
        <div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 size-5 -translate-y-1/2 text-muted-foreground" /><Input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} className="h-12 pl-11" placeholder="Try ‘web development’, ‘accounting’ or 62012" aria-label="Search SIC codes" /></div>
        <div className="flex flex-wrap gap-2" aria-label="Suggested SIC searches">{sicSuggestions.map((suggestion) => <Button key={suggestion} type="button" size="sm" variant="outline" onClick={() => setQuery(suggestion)}>{suggestion}</Button>)}</div>
        {!deferredQuery ? <div className="border-2 border-dashed p-6"><p className="font-black">Start with what the company does</p><p className="mt-1 text-sm text-muted-foreground">Use plain English. Search works across all {sicOptions.length.toLocaleString("en-GB")} official SIC activities.</p></div> : results.length ? <div className="max-h-[620px] divide-y-2 overflow-y-auto border-2">{results.map((option) => { const checked = selected.includes(option.code); return <button key={option.code} type="button" onClick={() => toggle(option.code)} disabled={!checked && selected.length >= 20} className={`flex w-full items-start justify-between gap-4 p-4 text-left transition hover:bg-muted disabled:cursor-not-allowed disabled:opacity-45 ${checked ? "bg-[hsl(var(--chart-2))]" : "bg-background"}`} aria-pressed={checked}><div><p className="font-black">{option.code}</p><p className="mt-1 text-sm text-muted-foreground">{option.description}</p></div><span className={`flex size-7 shrink-0 items-center justify-center border-2 ${checked ? "bg-foreground text-background" : "bg-background"}`}>{checked ? <Check className="size-4" /> : null}</span></button> })}</div> : <div className="border-2 border-dashed p-6 text-sm text-muted-foreground">No SIC codes match “{query}”. Try a broader activity such as “software” or “property”.</div>}
      </CardContent>
    </Card>
    <Card className="h-fit xl:sticky xl:top-24">
      <CardHeader><div className="flex items-center justify-between gap-3"><div><CardTitle>Selected activities</CardTitle><CardDescription>These become the audience rules for your new campaign.</CardDescription></div><Badge variant="outline">{selected.length}/20</Badge></div></CardHeader>
      <CardContent className="space-y-4">
        {selected.length ? <div className="space-y-2">{selected.map((code) => <div key={code} className="flex items-start justify-between gap-3 border-2 p-3"><div><p className="font-black">{code}</p><p className="mt-1 text-xs text-muted-foreground">{SIC_LABELS[code]}</p></div><Button type="button" size="icon" variant="ghost" onClick={() => toggle(code)} aria-label={`Remove SIC code ${code}`}><X className="size-4" /></Button></div>)}</div> : <p className="border-2 border-dashed p-5 text-sm text-muted-foreground">Select one or more activities from the search results.</p>}
        {selected.length ? <Button asChild className="w-full"><NextLink href={`/app/campaigns/new?sicCodes=${encodeURIComponent(selected.join(","))}`}>Use in a new campaign <ArrowRight className="ml-2 size-4" /></NextLink></Button> : <Button className="w-full" disabled>Use in a new campaign</Button>}
        <p className="text-xs leading-5 text-muted-foreground">Tip: choose only closely related activities. A focused audience usually produces more relevant company matches.</p>
      </CardContent>
    </Card>
  </div>
}

function CampaignSummary({ radars, leads, batches, mailItems, sender, newCompaniesLast30Days, onOpenSettings }: { radars: AgencyRadar[]; leads: AgencyLead[]; batches: MailBatch[]; mailItems: MailItem[]; sender: SenderProfile | null; newCompaniesLast30Days: number | null; onOpenSettings: () => void }) {
  const pending = batches.filter((batch) => batch.status === "pending_approval").length
  const recent = mailItems.filter((item) => ["submitted", "production", "dispatched", "failed", "blocked"].includes(item.status)).slice(0, 6)
  const setupReady = Boolean(sender?.agencyName && sender.replyEmail && sender.address.address1 && sender.address.town && sender.address.postcode && sender.website && sender.optOutText)
  return <div className="space-y-5">
    {!setupReady ? <Card className="border-[hsl(var(--chart-4))]"><CardHeader><CardTitle>Complete sender setup</CardTitle><CardDescription>Add your business name, reply email, UK postal address, website and opt-out text before activating a campaign.</CardDescription></CardHeader><CardContent><Button type="button" onClick={onOpenSettings}>Open settings</Button></CardContent></Card> : null}
    <div className="grid gap-4 sm:grid-cols-3"><Metric label="Active campaigns" value={radars.filter((item) => item.isActive).length} /><Metric label="Awaiting approval" value={pending} /><Metric label="New UK companies incorporated in the last 30 days" value={newCompaniesLast30Days} /></div>
    <Card><CardHeader><CardTitle>Campaigns</CardTitle><CardDescription>Open a campaign to review matches, prepare letters and approve physical mail.</CardDescription></CardHeader><CardContent>{radars.length ? <div className="grid gap-3 lg:grid-cols-2">{radars.map((radar) => { const campaignLeads = leads.filter((lead) => lead.radarId === radar.id); const campaignBatches = batches.filter((batch) => batch.radarId === radar.id); return <NextLink href={`/app/campaigns/${radar.id}`} key={radar.id} className="group border-2 bg-background p-4 hover:shadow-[4px_4px_0_0_hsl(var(--foreground))]"><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><p className="font-black">{radar.name}</p><Badge variant={radar.isActive ? "default" : "outline"}>{radar.isActive ? "Active" : "Paused"}</Badge></div><p className="mt-2 text-sm text-muted-foreground">Daily scan · {radar.dailySendLimit ?? 20}/day · {radar.monthlySendLimit ?? 400}/month</p></div><ArrowRight className="size-5 transition-transform group-hover:translate-x-1" /></div><div className="mt-4 grid grid-cols-2 gap-2 text-sm"><InfoMini label="Matches" value={campaignLeads.length} /><InfoMini label="Approval batches" value={campaignBatches.filter((batch) => batch.status === "pending_approval").length} /></div></NextLink> })}</div> : <Empty text="No campaigns yet. Complete sender setup, then create your first campaign." />}</CardContent></Card>
    <Card><CardHeader><CardTitle>Recent delivery activity</CardTitle><CardDescription>Latest Frankk production, dispatch and failure updates.</CardDescription></CardHeader><CardContent>{recent.length ? <div className="divide-y-2 border-2">{recent.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-2 p-3"><div><p className="font-bold">{item.companyName}</p><p className="text-xs text-muted-foreground">{item.companyNumber}</p></div><Badge variant="outline">{mailStatus(item)}</Badge></div>)}</div> : <Empty text="Approved letters will appear here." />}</CardContent></Card>
  </div>
}
function Metric({ label, value }: { label: string; value: number | null }) { return <Card><CardHeader className="pb-2"><CardDescription>{label}</CardDescription><CardTitle className="text-4xl">{value === null ? "—" : value.toLocaleString("en-GB")}</CardTitle>{value === null ? <p className="text-xs text-muted-foreground">Companies House data is temporarily unavailable.</p> : null}</CardHeader></Card> }
function InfoMini({ label, value }: { label: string; value: number }) { return <div className="border p-2"><p className="text-xs text-muted-foreground">{label}</p><p className="font-black">{value}</p></div> }

export function SegmentRadarWizard({ segments, templateLibrary, workspaceTemplates, sender, sampleCompany, onSubmit, initialTemplateId, initialSicCodes = [] }: { segments: AgencySegment[]; templateLibrary: AgencyTemplateLibraryItem[]; workspaceTemplates: LetterTemplate[]; sender: SenderProfile | null; sampleCompany?: AgencyLead["company"]; onSubmit: (values: { name: string; sicCodes: string[]; cities?: string[]; keywords?: string[]; deliveryFrequency?: "daily" | "weekly"; autoQueueLetters?: boolean; mailTemplateId?: string; templateLibraryId?: string; segmentSlug?: string; segmentSlugs?: string[]; serviceFocus?: string[]; companyAgeDays?: number; postcodePrefixes?: string[]; dailySendLimit?: number; monthlySendLimit?: number }) => void; initialTemplateId?: string; initialSicCodes?: string[] }) {
  const [step, setStep] = React.useState(1)
  const [selectedSlugs, setSelectedSlugs] = React.useState<string[]>([])
  const [templateId, setTemplateId] = React.useState("")
  const [name, setName] = React.useState("")
  const [subject, setSubject] = React.useState("")
  const [bodyHtml, setBodyHtml] = React.useState("")
  const [ctaText, setCtaText] = React.useState("")
  const [ctaUrl, setCtaUrl] = React.useState("")
  const [signature, setSignature] = React.useState("")
  const [sicCodes, setSicCodes] = React.useState("")
  const [cities, setCities] = React.useState<string[]>([])
  const [customRegion, setCustomRegion] = React.useState("")
  const [postcodePrefixes, setPostcodePrefixes] = React.useState("")
  const [keywords, setKeywords] = React.useState("")
  const [serviceFocus, setServiceFocus] = React.useState<string[]>([])
  const [customService, setCustomService] = React.useState("")
  const [companyAgeDays, setCompanyAgeDays] = React.useState(30)
  const [dailyLimit, setDailyLimit] = React.useState(20)
  const [monthlyLimit, setMonthlyLimit] = React.useState(400)
  const [frequency, setFrequency] = React.useState<"daily" | "weekly">("daily")
  const [autoQueue, setAutoQueue] = React.useState(false)
  const [draftHydrated, setDraftHydrated] = React.useState(false)
  React.useEffect(() => { try { const draft = JSON.parse(sessionStorage.getItem("company-radar-campaign-draft") ?? "null") as Record<string, unknown> | null; if (draft) { setStep(initialSicCodes.length ? 1 : Number(draft.step) || 1); setSelectedSlugs(initialSicCodes.length ? [] : Array.isArray(draft.selectedSlugs) ? draft.selectedSlugs as string[] : []); setTemplateId(initialTemplateId || String(draft.templateId ?? "")); setName(initialSicCodes.length ? "Custom SIC campaign" : String(draft.name ?? "")); setSicCodes(initialSicCodes.length ? initialSicCodes.join(", ") : String(draft.sicCodes ?? "")); setCities(Array.isArray(draft.cities) ? draft.cities as string[] : []); setCustomRegion(String(draft.customRegion ?? "")); setPostcodePrefixes(String(draft.postcodePrefixes ?? "")); setKeywords(String(draft.keywords ?? "")); setServiceFocus(Array.isArray(draft.serviceFocus) ? draft.serviceFocus as string[] : []); setCompanyAgeDays(Number(draft.companyAgeDays) || 30); setDailyLimit(Number(draft.dailyLimit) || 20); setMonthlyLimit(Number(draft.monthlyLimit) || 400) } else { if (initialTemplateId) setTemplateId(initialTemplateId); if (initialSicCodes.length) { setName("Custom SIC campaign"); setSicCodes(initialSicCodes.join(", ") ) } } } catch { /* start a clean draft */ } finally { setDraftHydrated(true) } }, [initialTemplateId, initialSicCodes])
  React.useEffect(() => { if (!draftHydrated) return; sessionStorage.setItem("company-radar-campaign-draft", JSON.stringify({ step, selectedSlugs, templateId, name, sicCodes, cities, customRegion, postcodePrefixes, keywords, serviceFocus, companyAgeDays, dailyLimit, monthlyLimit })) }, [cities, companyAgeDays, customRegion, dailyLimit, draftHydrated, keywords, monthlyLimit, name, postcodePrefixes, selectedSlugs, serviceFocus, sicCodes, step, templateId])
  const parsed = (value: string) => value.split(",").map((item) => item.trim()).filter(Boolean)
  const cityOptions = ["London", "Manchester", "Birmingham", "Leeds", "Bristol", "Glasgow", "Edinburgh"]
  const selectedSegments = segments.filter((item) => selectedSlugs.includes(item.slug))
  const templates = selectedSlugs.length ? templateLibrary.filter((item) => selectedSlugs.includes(item.segmentSlug)) : templateLibrary
  const savedTemplates = workspaceTemplates.filter((item) => !item.isCampaignSnapshot)
  const template = templateLibrary.find((item) => item.id === templateId) ?? templates[0]
  const savedTemplate = savedTemplates.find((item) => item.id === templateId)
  const suggestedServices = Array.from(new Set(templates.flatMap((item) => item.serviceFocus ?? [])))
  const selectedCityLabels = cities.length ? cities : customRegion ? [customRegion] : []
  const previewSample = sampleCompany ?? DEFAULT_LETTER_SAMPLE
  function toggleSegment(slug: string) {
    const next = selectedSlugs.includes(slug) ? selectedSlugs.filter((item) => item !== slug) : [...selectedSlugs, slug]
    const chosen = segments.filter((item) => next.includes(item.slug))
    const nextTemplate = templateLibrary.find((item) => item.id === chosen[0]?.defaultTemplateId) ?? templateLibrary.find((item) => next.includes(item.segmentSlug))
    setSelectedSlugs(next); setName(chosen.map((item) => item.name).join(" + ") || "Custom campaign"); setSicCodes(Array.from(new Set(chosen.flatMap((item) => item.sicCodes))).join(", ")); setCompanyAgeDays(chosen[0]?.defaultFilters.companyAgeDays ?? 30); setTemplateId(nextTemplate?.id ?? ""); setSubject(nextTemplate?.subject ?? ""); setBodyHtml(nextTemplate?.bodyHtml ?? ""); setCtaText(nextTemplate?.ctaText ?? ""); setCtaUrl(nextTemplate?.ctaUrl ?? ""); setSignature(nextTemplate?.signature ?? ""); setServiceFocus(Array.from(new Set(chosen.flatMap((item) => templateLibrary.find((tpl) => tpl.id === item.defaultTemplateId)?.serviceFocus ?? []))))
  }
  function toggleCity(city: string) { setCities((current) => current.includes(city) ? current.filter((item) => item !== city) : [...current, city]) }
  function chooseTemplate(id: string) { const item = templateLibrary.find((candidate) => candidate.id === id); const saved = savedTemplates.find((candidate) => candidate.id === id); setTemplateId(id); setSubject(item?.subject ?? saved?.subject ?? ""); setBodyHtml(item?.bodyHtml ?? saved?.bodyHtml ?? ""); setCtaText(item?.ctaText ?? saved?.ctaText ?? ""); setCtaUrl(item?.ctaUrl ?? saved?.ctaUrl ?? ""); setSignature(item?.signature ?? saved?.signature ?? ""); setServiceFocus(item?.serviceFocus ?? saved?.serviceFocus ?? []) }
  function addCustomService() { const value = customService.trim(); if (value && !serviceFocus.includes(value)) setServiceFocus((current) => [...current, value]); setCustomService("") }
  const senderReady = Boolean(sender?.agencyName && sender.replyEmail && sender.address.address1 && sender.address.town && sender.address.postcode && sender.website && sender.optOutText)
  const canContinue = step === 1 ? Boolean(parsed(sicCodes).length) : step === 2 ? Boolean(templateId) : senderReady
  function submit() { onSubmit({ name: name.trim() || "Custom campaign", sicCodes: parsed(sicCodes), cities: selectedCityLabels, keywords: parsed(keywords), deliveryFrequency: "daily", autoQueueLetters: false, mailTemplateId: savedTemplate?.id, templateLibraryId: savedTemplate ? undefined : template?.id, segmentSlug: selectedSlugs[0], segmentSlugs: selectedSlugs, serviceFocus: savedTemplate?.serviceFocus ?? serviceFocus, companyAgeDays, postcodePrefixes: parsed(postcodePrefixes), dailySendLimit: dailyLimit, monthlySendLimit: monthlyLimit }) }
  return <Card><CardHeader className="pb-3"><div className="flex items-start justify-between gap-3"><div><CardTitle>{step === 2 ? "Choose and personalise your letter" : "Create a campaign"}</CardTitle><CardDescription>{step === 2 ? "Start with a proven template, then make the message yours. Company details are personalised automatically for every recipient." : "Choose audiences and locations, then prepare the letter."}</CardDescription></div><Badge variant="outline">{step}/3</Badge></div><div className="mt-3 grid grid-cols-3 gap-1 text-xs font-black">{["Audience", "Letter", "Review"].map((label, index) => <div key={label} className={`border-2 px-2 py-2 ${step === index + 1 ? "bg-[hsl(var(--chart-2))]" : step > index + 1 ? "bg-[hsl(var(--chart-3))]" : "bg-muted"}`}>{step > index + 1 ? <Check className="mr-1 inline size-3" /> : `${index + 1}. `}{label}</div>)}</div></CardHeader><CardContent className="space-y-4">
    {step === 1 ? <><p className="text-sm font-bold">Choose one or more audiences</p><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{segments.map((item) => <button type="button" key={item.slug} onClick={() => toggleSegment(item.slug)} className={`border-2 p-4 text-left transition ${selectedSlugs.includes(item.slug) ? "bg-[hsl(var(--chart-2))]" : "bg-background hover:bg-muted"}`}><div className="flex items-start justify-between gap-2"><p className="font-black">{item.name}</p><span className={`flex size-5 items-center justify-center rounded-full border-2 text-xs ${selectedSlugs.includes(item.slug) ? "bg-foreground text-background" : ""}`}>{selectedSlugs.includes(item.slug) ? "✓" : ""}</span></div><p className="mt-1 text-xs text-muted-foreground">{item.persona}</p></button>)}<button type="button" onClick={() => { setSelectedSlugs([]); setName("Custom campaign"); setSicCodes("") }} className="border-2 border-dashed p-4 text-left hover:bg-muted"><p className="font-black">+ Create custom audience</p><p className="mt-1 text-xs text-muted-foreground">Start with your own SIC and location rules.</p></button></div><div className="grid gap-3 border-t-2 pt-3 sm:grid-cols-2"><label className="text-sm font-bold">Campaign name<Input value={name} onChange={(event) => setName(event.target.value)} className="mt-1" placeholder="New agency prospects" /></label><label className="text-sm font-bold">SIC codes<Input value={sicCodes} onChange={(event) => setSicCodes(event.target.value)} className="mt-1" placeholder="62012, 62020" /></label><div className="sm:col-span-2"><p className="mb-2 text-sm font-bold">Cities / regions</p><div className="flex flex-wrap gap-2">{cityOptions.map((city) => <button type="button" key={city} onClick={() => toggleCity(city)} className={`border-2 px-3 py-2 text-sm font-bold ${cities.includes(city) ? "bg-[hsl(var(--chart-2))]" : "bg-background hover:bg-muted"}`}>{city}</button>)}<button type="button" onClick={() => setCities([])} className={`border-2 px-3 py-2 text-sm font-bold ${cities.length === 0 && !customRegion ? "bg-[hsl(var(--chart-3))]" : "bg-background"}`}>All UK</button></div><Input value={customRegion} onChange={(event) => { setCustomRegion(event.target.value); setCities([]) }} className="mt-2" placeholder="Custom region or town (optional)" /></div><label className="text-sm font-bold">Postcode prefixes<Input value={postcodePrefixes} onChange={(event) => setPostcodePrefixes(event.target.value)} className="mt-1" placeholder="E, EC, N (optional)" /></label><label className="text-sm font-bold">Keywords<Input value={keywords} onChange={(event) => setKeywords(event.target.value)} className="mt-1" placeholder="AI, studio, agency" /></label><label className="text-sm font-bold">New company age: {companyAgeDays} days<input className="mt-2 w-full accent-[hsl(var(--chart-2))]" type="range" min="1" max="90" value={companyAgeDays} onChange={(event) => setCompanyAgeDays(Number(event.target.value))} /></label><div className="grid gap-3 sm:col-span-2 sm:grid-cols-2"><label className="text-sm font-bold">Daily send limit<Input type="number" min={1} value={dailyLimit} onChange={(event) => setDailyLimit(Number(event.target.value))} className="mt-1" /></label><label className="text-sm font-bold">Monthly send limit<Input type="number" min={1} value={monthlyLimit} onChange={(event) => setMonthlyLimit(Number(event.target.value))} className="mt-1" /></label></div></div></> : null}
    {step === 2 ? <div className="space-y-6">
      <section aria-labelledby="starting-template-heading" className="space-y-3">
        <div><h3 id="starting-template-heading" className="font-black">Choose your campaign letter</h3><p className="text-sm text-muted-foreground">Pick a saved letter or start from a platform design. Edit letters in Letter templates; activation stores a frozen campaign copy.</p></div>
        {savedTemplates.length ? <><p className="text-xs font-black uppercase tracking-widest">My templates</p><div className="grid gap-2 sm:grid-cols-2">{savedTemplates.map((item) => { const selected = item.id === templateId; return <button type="button" key={item.id} onClick={() => chooseTemplate(item.id)} aria-pressed={selected} className={`w-full border-2 p-3 text-left ${selected ? "bg-[hsl(var(--chart-2))]" : "bg-background hover:bg-muted"}`}><div className="flex justify-between gap-2"><p className="font-bold">{item.name}</p>{selected ? <Badge><Check className="mr-1 size-3" />Selected</Badge> : null}</div><p className="mt-2 text-xs text-muted-foreground">{item.layout?.design?.preset ?? "minimal"} design · Saved workspace letter</p></button>})}</div></> : null}
        <p className="text-xs font-black uppercase tracking-widest">Starting templates</p><div className="grid gap-2 sm:grid-cols-2">{templates.map((item) => { const selected = item.id === templateId; return <button type="button" key={item.id} onClick={() => chooseTemplate(item.id)} aria-pressed={selected} className={`w-full border-2 p-3 text-left transition ${selected ? "bg-[hsl(var(--chart-2))]" : "bg-background hover:bg-muted"}`}><div className="flex items-start justify-between gap-3"><p className="font-bold">{item.name}</p>{selected ? <Badge className="shrink-0"><Check className="mr-1 size-3" />Selected</Badge> : null}</div><p className="mt-1 text-xs text-muted-foreground">{item.description}</p><p className="mt-2 text-xs font-bold">{(item.serviceFocus ?? []).slice(0, 4).join(" · ")}</p></button> })}</div>
        {templateId ? <div className="grid gap-5 border-t-2 pt-5 lg:grid-cols-[minmax(0,1fr)_380px]"><div><p className="font-black">Selected letter</p><p className="mt-1 text-sm text-muted-foreground">This is the same A4 layout used by the editor and final PDF, shown with a sample recipient.</p><Button asChild className="mt-3" variant="outline"><NextLink href={`/app/templates/${templateId}?returnTo=/app/campaigns/new`}>Edit this letter <ArrowRight className="ml-2 size-4" /></NextLink></Button></div><div><div className="mb-2 flex items-center justify-between gap-2 text-xs font-bold text-muted-foreground"><span>Sample recipient</span><span>Nothing will be sent</span></div><ScaledLetterPreview subject={savedTemplate?.subject ?? template?.subject ?? subject} bodyHtml={savedTemplate?.bodyHtml ?? template?.bodyHtml ?? bodyHtml} ctaText={savedTemplate?.ctaText ?? template?.ctaText ?? ctaText} ctaUrl={savedTemplate?.ctaUrl ?? template?.ctaUrl ?? ctaUrl} signature={savedTemplate?.signature ?? template?.signature ?? signature} sender={sender ?? undefined} serviceFocus={savedTemplate?.serviceFocus ?? template?.serviceFocus ?? serviceFocus} layout={savedTemplate?.layout ?? template?.layout} sample={previewSample} /></div></div> : null}
      </section>
      <section aria-labelledby="personalise-content-heading" className="hidden space-y-4 border-t-2 pt-5">
        <div><h3 id="personalise-content-heading" className="font-black">2 · Personalise the content</h3><p className="text-sm text-muted-foreground">Edit the message below. The preview uses sample company details so you can see the finished letter.</p></div>
        <div className="grid min-w-0 gap-5 lg:grid-cols-[minmax(0,1.25fr)_minmax(300px,0.75fr)]">
          <div className="min-w-0 space-y-5">
            <label className="block text-sm font-bold">Letter headline<span className="mt-1 block text-xs font-normal text-muted-foreground">The main heading printed near the top of the letter.</span><Input value={subject} onChange={(event) => setSubject(event.target.value)} className="mt-2" placeholder="A quick idea for {{company_name}}" aria-invalid={!subject.trim()} />{!subject.trim() ? <span className="mt-1 block text-xs font-medium text-destructive">Add a headline to continue.</span> : null}</label>
            <div><p className="text-sm font-bold">Services to mention</p><p className="mt-1 text-xs text-muted-foreground">Select the services most relevant to this audience.</p><div className="mt-2 flex flex-wrap gap-2">{suggestedServices.map((service) => <button type="button" key={service} onClick={() => setServiceFocus((current) => current.includes(service) ? current.filter((item) => item !== service) : [...current, service])} className={`border-2 px-2 py-1 text-xs font-bold ${serviceFocus.includes(service) ? "bg-[hsl(var(--chart-2))]" : "bg-background"}`}>{service}</button>)}<div className="flex min-w-0 gap-1"><Input value={customService} onChange={(event) => setCustomService(event.target.value)} className="h-8 min-w-0 w-40" placeholder="Add a service" /><Button type="button" size="sm" variant="outline" onClick={addCustomService}>Add</Button></div></div></div>
            <div><p className="text-sm font-bold">Main message</p><p className="mb-2 mt-1 text-xs text-muted-foreground">Write the body of the letter. Personalised company details are inserted automatically when it is prepared.</p><RichLetterEditor value={bodyHtml} onChange={setBodyHtml} />{!bodyHtml.trim() ? <p className="mt-1 text-xs font-medium text-destructive">Add a message to continue.</p> : null}</div>
            <fieldset className="space-y-2"><legend className="text-sm font-bold">Call to action</legend><p className="text-xs text-muted-foreground">Tell the reader what to do next and where the button or QR link should go.</p><div className="grid gap-2 sm:grid-cols-2"><label className="text-xs font-bold">Button text<Input value={ctaText} onChange={(event) => setCtaText(event.target.value)} className="mt-1" placeholder="Book a short introduction" /></label><label className="text-xs font-bold">Destination URL<Input value={ctaUrl} onChange={(event) => setCtaUrl(event.target.value)} className="mt-1" placeholder="https://youragency.co.uk/book" /></label></div></fieldset>
            <label className="block text-sm font-bold">Sign-off / signature<span className="mt-1 block text-xs font-normal text-muted-foreground">The name or closing line shown at the end of the letter.</span><Input value={signature} onChange={(event) => setSignature(event.target.value)} className="mt-2" placeholder="Your name, Your agency" aria-invalid={!signature.trim()} />{!signature.trim() ? <span className="mt-1 block text-xs font-medium text-destructive">Add a sign-off to continue.</span> : null}</label>
          </div>
          <aside className="min-w-0 self-start border-2 bg-muted p-3 lg:sticky lg:top-4"><div className="mb-3 flex flex-wrap items-start justify-between gap-2"><div><p className="font-black">Live A4 preview</p><p className="text-xs text-muted-foreground">Uses sample company details.</p></div><Badge variant="outline">Preview only · Nothing sent</Badge></div><div className="mx-auto aspect-[210/297] w-full max-w-[440px] overflow-auto border-2 bg-background"><LetterPreview subject={subject} bodyHtml={bodyHtml} ctaText={ctaText} ctaUrl={ctaUrl} signature={signature} sender={sender ?? undefined} serviceFocus={serviceFocus} /></div></aside>
        </div>
      </section>
    </div> : null}
    {step === 3 ? <div className="space-y-4"><div className="grid gap-3 lg:grid-cols-[1fr_0.8fr_340px]"><div className="border-2 p-3 text-sm"><p className="text-xs font-black uppercase text-muted-foreground">Audience</p><p className="mt-2 font-black">{selectedSegments.map((item) => item.name).join(" + ") || "Custom audience"}</p><p className="mt-1">{sicCodes || "Custom SIC rules"}</p><p className="mt-1">{selectedCityLabels.join(", ") || "All UK"} · New within {companyAgeDays} days</p></div><div className="border-2 p-3 text-sm"><p className="text-xs font-black uppercase text-muted-foreground">Operation</p><p className="mt-2 font-black">Daily automatic scan</p><p className="mt-1">{dailyLimit}/day · {monthlyLimit}/month</p><p className="mt-1">1 approved letter = 1 credit</p><p className="mt-1">Owner approval required before every physical send</p></div><div><p className="mb-2 text-xs font-bold text-muted-foreground">Selected letter · sample recipient</p><ScaledLetterPreview subject={savedTemplate?.subject ?? template?.subject ?? subject} bodyHtml={savedTemplate?.bodyHtml ?? template?.bodyHtml ?? bodyHtml} ctaText={savedTemplate?.ctaText ?? template?.ctaText ?? ctaText} ctaUrl={savedTemplate?.ctaUrl ?? template?.ctaUrl ?? ctaUrl} signature={savedTemplate?.signature ?? template?.signature ?? signature} sender={sender ?? undefined} serviceFocus={savedTemplate?.serviceFocus ?? template?.serviceFocus ?? serviceFocus} layout={savedTemplate?.layout ?? template?.layout} sample={previewSample} /></div></div><div className="border-2 bg-muted p-3 text-sm"><p className="font-black">Activation starts the first company scan</p><p className="mt-1 text-muted-foreground">No letter is printed, charged or posted until you select matches, review the real Frankk PDF and approve the batch.</p></div>{!sender?.agencyName || !sender.replyEmail || !sender.address.address1 || !sender.address.town || !sender.address.postcode || !sender.website || !sender.optOutText ? <div className="border-2 border-destructive bg-destructive/10 p-3 text-sm font-bold text-destructive">Complete sender setup in Settings before activating this campaign.</div> : null}<label className="block text-sm font-bold">Campaign name<Input value={name} onChange={(event) => setName(event.target.value)} className="mt-1" /></label></div> : null}
    <div className="flex justify-between gap-2 border-t-2 pt-4">{step > 1 ? <Button type="button" variant="outline" onClick={() => setStep((value) => value - 1)}>Back</Button> : <span />}{step < 3 ? <Button type="button" disabled={!canContinue} onClick={() => setStep((value) => value + 1)}>{step === 2 ? "Continue to review" : "Continue"} <ArrowRight className="ml-2 size-4" /></Button> : <Button type="button" disabled={!canContinue} onClick={submit}>Activate campaign <ArrowRight className="ml-2 size-4" /></Button>}</div>
  </CardContent></Card>
}

export function TemplateStudio({ templates, templateLibrary, leads, sender, owner, onSave, onArchive, onSaveSender, initialTemplateId, returnTo }: { templates: LetterTemplate[]; templateLibrary: AgencyTemplateLibraryItem[]; leads: AgencyLead[]; sender: SenderProfile | null; owner: boolean; onSave: (draft: TemplateDraft) => Promise<string | undefined>; onArchive: (id: string) => Promise<void>; onSaveSender: (sender: SenderProfile) => void; initialTemplateId?: string; returnTo?: string }) {
  const initialMine = Boolean(initialTemplateId && templates.some((item) => item.id === initialTemplateId))
  const initialLibrary = Boolean(initialTemplateId && templateLibrary.some((item) => item.id === initialTemplateId))
  const [view, setView] = React.useState<"gallery" | "editor">(initialTemplateId ? "editor" : "gallery")
  const [localTemplates, setLocalTemplates] = React.useState(templates)
  const [selectedKey, setSelectedKey] = React.useState(initialMine ? `mine:${initialTemplateId}` : initialLibrary ? `platform:${initialTemplateId}` : templates[0] ? `mine:${templates[0].id}` : templateLibrary[0] ? `platform:${templateLibrary[0].id}` : "")
  const selectedMine = selectedKey.startsWith("mine:")
  const selectedId = selectedKey.split(":")[1]
  const selected = selectedMine ? localTemplates.find((item) => item.id === selectedId) : templateLibrary.find((item) => item.id === selectedId)
  const selectedLibrary = !selectedMine ? templateLibrary.find((item) => item.id === selectedId) : undefined
  const [name, setName] = React.useState(""); const [serviceFocus, setServiceFocus] = React.useState<string[]>([]); const [customService, setCustomService] = React.useState(""); const [layout, setLayout] = React.useState<LetterLayout>(defaultLetterLayout())
  const [selectedBlockId, setSelectedBlockId] = React.useState<string | null>(null); const [panel, setPanel] = React.useState<"content" | "brand" | "personalise">("content"); const [saveState, setSaveState] = React.useState<"idle" | "pending" | "saving" | "saved" | "error">("idle"); const [saveError, setSaveError] = React.useState(""); const [revision, setRevision] = React.useState(0); const [overflowing, setOverflowing] = React.useState(false)
  const templateIdRef = React.useRef<string | undefined>(selectedMine ? selectedId : undefined); const sourceIdRef = React.useRef<string | undefined>(selectedLibrary?.id); const saveChain = React.useRef(Promise.resolve()); const savedRevision = React.useRef(0); const latestRevision = React.useRef(0)
  const [logoUrl, setLogoUrl] = React.useState(sender?.logoUrl ?? ""); const [accentColor, setAccentColor] = React.useState(sender?.accentColor ?? DEFAULT_ACCENT_COLOR); const [primaryColor, setPrimaryColor] = React.useState(sender?.primaryColor ?? "#111827"); const [textColor, setTextColor] = React.useState(sender?.textColor ?? "#111827"); const [fontFamily, setFontFamily] = React.useState(sender?.fontFamily ?? "Arial"); const [headerAlignment, setHeaderAlignment] = React.useState<"left" | "center" | "right">(sender?.headerAlignment ?? "left"); const [agencyName, setAgencyName] = React.useState(sender?.agencyName ?? "Your agency"); const [website, setWebsite] = React.useState(sender?.website ?? ""); const [replyEmail, setReplyEmail] = React.useState(sender?.replyEmail ?? "reply@agency.com"); const [optOutText, setOptOutText] = React.useState(sender?.optOutText ?? "To stop receiving marketing by post, use this reference."); const [address1, setAddress1] = React.useState(sender?.address.address1 ?? ""); const [town, setTown] = React.useState(sender?.address.town ?? ""); const [postcode, setPostcode] = React.useState(sender?.address.postcode ?? "")
  const sample = leads[0]?.company ?? { companyName: "Northstar Digital Ltd", companyNumber: "12345678", incorporationDate: "23 July 2026", location: "London", sicCodes: ["62012"] }
  const previewSender: SenderProfile = { agencyName, replyEmail, website, optOutText, logoUrl, accentColor, primaryColor, textColor, fontFamily, headerAlignment, address: { address1, town, postcode, country: "GB" } }
  const invalidQr = layout.blocks.some((item) => item.type === "qr" && !normalizeExternalUrl(item.url))
  React.useEffect(() => setLocalTemplates(templates), [templates])
  React.useEffect(() => { if (!selected) return; setName(selected.name); setServiceFocus(selected.serviceFocus ?? []); setLayout(normalizeLetterLayout("layout" in selected ? selected.layout : undefined, selected)); templateIdRef.current = selectedMine ? selectedId : undefined; sourceIdRef.current = selectedLibrary?.id; setSelectedBlockId(null); setSaveState("idle"); setRevision(0); savedRevision.current = 0; latestRevision.current = 0 }, [selectedKey])
  React.useEffect(() => { if (view !== "editor" || revision === 0 || revision <= savedRevision.current || !owner) return; setSaveState("pending"); const timer = window.setTimeout(() => { const snapshot = { name, layout, serviceFocus }; const targetRevision = revision; saveChain.current = saveChain.current.then(async () => { setSaveState("saving"); setSaveError(""); const legacy = layoutToLegacy(snapshot.layout); try { const id = await onSave({ id: templateIdRef.current, sourceTemplateId: templateIdRef.current ? undefined : sourceIdRef.current, name: snapshot.name.trim() || "Untitled letter", ...legacy, serviceFocus: snapshot.serviceFocus, layout: snapshot.layout, isDefault: false }); if (id) { templateIdRef.current = id; setLocalTemplates((current) => { const next: LetterTemplate = { id, workspaceId: current.find((item) => item.id === id)?.workspaceId ?? "current", name: snapshot.name.trim() || "Untitled letter", ...legacy, serviceFocus: snapshot.serviceFocus, layout: snapshot.layout, isDefault: false, createdAt: current.find((item) => item.id === id)?.createdAt ?? new Date().toISOString() }; return [next, ...current.filter((item) => item.id !== id)] }) } savedRevision.current = targetRevision; setSaveState(targetRevision === latestRevision.current ? "saved" : "pending") } catch (error) { setSaveError(errorMessage(error)); setSaveState("error") } }); }, 700); return () => window.clearTimeout(timer) }, [layout, name, onSave, owner, revision, serviceFocus, view])
  React.useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (["pending", "saving", "error"].includes(saveState)) event.preventDefault() }; window.addEventListener("beforeunload", warn); return () => window.removeEventListener("beforeunload", warn) }, [saveState])
  function markDirty() { setRevision((value) => { const next = value + 1; latestRevision.current = next; return next }) }
  function changeLayout(next: LetterLayout) { setLayout(next); markDirty() }
  function changeName(value: string) { setName(value); markDirty() }
  function choose(key: string) { setSelectedKey(key); setView("editor") }
  async function archive(id: string, templateName: string) { if (!window.confirm(`Remove “${templateName}” from My Templates? Past campaigns and sends will be kept.`)) return; try { await onArchive(id); setLocalTemplates((current) => current.filter((item) => item.id !== id)); if (selectedKey === `mine:${id}`) setSelectedKey(templateLibrary[0] ? `platform:${templateLibrary[0].id}` : "") } catch (error) { setSaveError(errorMessage(error)); setSaveState("error") } }
  function addCustomService() { const value = customService.trim(); if (!value || serviceFocus.includes(value)) return; setServiceFocus((current) => [...current, value]); setCustomService(""); markDirty() }
  function saveBranding() { onSaveSender(previewSender) }
  function finish() { if (returnTo) { const target = new URL(returnTo, window.location.origin); if (templateIdRef.current) target.searchParams.set("templateId", templateIdRef.current); window.location.assign(`${target.pathname}${target.search}`) } else setView("gallery") }
  if (view === "gallery") return <TemplateGallery templates={localTemplates} library={templateLibrary} owner={owner} sender={previewSender} sample={sample} onChoose={choose} onArchive={archive} />
  return <div className="overflow-hidden border-2 bg-card shadow-[6px_6px_0_0_hsl(var(--foreground))]">
    <header className="flex flex-wrap items-center gap-3 border-b-2 bg-foreground px-4 py-3 text-background"><div className="flex min-w-[280px] flex-1 items-center gap-3"><Button type="button" size="icon" variant="secondary" disabled={["pending", "saving", "error"].includes(saveState)} onClick={finish} aria-label="Back to templates"><ArrowLeft className="size-4" /></Button><div className="min-w-0 flex-1"><p className="text-xs opacity-70">Letter templates / {selectedMine || templateIdRef.current ? "Workspace draft" : "Platform template"}</p><input value={name} onChange={(event) => changeName(event.target.value)} className="w-full bg-transparent text-lg font-black outline-none" aria-label="Template name" /></div></div><div className="ml-auto flex items-center gap-3 text-xs font-bold"><span aria-live="polite">{saveState === "saving" ? "Saving…" : saveState === "pending" ? "Unsaved changes" : saveState === "saved" ? "Saved" : saveState === "error" ? "Save failed" : "Ready"}</span><Button type="button" variant="secondary" disabled={overflowing || saveState === "saving" || saveState === "pending" || saveState === "error"} onClick={finish}>Done</Button></div></header>
    {saveState === "error" ? <div className="flex flex-wrap items-center justify-between gap-2 border-b-2 bg-destructive/10 px-4 py-2 text-sm font-bold text-destructive"><span>{saveError}</span><Button type="button" size="sm" variant="outline" onClick={markDirty}>Retry save</Button></div> : null}
    {overflowing ? <div className="border-b-2 bg-[hsl(var(--chart-3))] px-4 py-2 text-sm font-bold">This letter exceeds one A4 page. Shorten it before finishing.</div> : null}
    {invalidQr ? <div className="border-b-2 bg-destructive/10 px-4 py-2 text-sm font-bold text-destructive">Complete or remove the QR block before finishing.</div> : null}
    <div className="grid min-w-0 lg:grid-cols-[72px_minmax(0,1fr)_320px]">
      <LetterToolbox onAdd={(type) => { const next = block(type, type === "paragraph" ? "Write your message…" : type === "heading" ? "Your heading" : type === "cta" ? "Learn more" : ""); const footerIndex = Math.max(0, layout.blocks.findIndex((item) => item.type === "footer")); changeLayout({ ...layout, blocks: [...layout.blocks.slice(0, footerIndex), next, ...layout.blocks.slice(footerIndex)] }); setSelectedBlockId(next.id); setPanel("content") }} />
      <main className="order-first min-w-0 bg-muted p-3 sm:p-6 lg:order-none lg:p-8"><div className="mx-auto max-w-[820px]"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-bold text-muted-foreground">Sample recipient · Automatically personalised when sent · Nothing will be sent</p><div className="flex flex-wrap gap-1" aria-label="Letter design preset">{(["minimal","modern","editorial"] as const).map((preset) => <button type="button" key={preset} onClick={() => changeLayout({ ...layout, design: { preset } })} className={`border px-2 py-1 text-[10px] font-bold capitalize ${layout.design?.preset === preset ? "bg-foreground text-background" : "bg-background"}`}>{preset}</button>)}</div></div><LetterCanvas layout={layout} sender={previewSender} sample={sample} serviceFocus={serviceFocus} selectedId={selectedBlockId} onSelect={(id) => { setSelectedBlockId(id); setPanel("content") }} onChange={changeLayout} onOverflow={setOverflowing} /></div></main>
      <LetterInspector panel={panel} setPanel={setPanel} selected={layout.blocks.find((item) => item.id === selectedBlockId)} onBlockChange={(changes) => selectedBlockId && changeLayout({ ...layout, blocks: layout.blocks.map((item) => item.id === selectedBlockId ? { ...item, ...changes } : item) })} serviceFocus={serviceFocus} setServiceFocus={(next) => { setServiceFocus(next); markDirty() }} customService={customService} setCustomService={setCustomService} addCustomService={addCustomService} sender={previewSender} setters={{ setAgencyName, setLogoUrl, setAccentColor, setPrimaryColor, setTextColor, setFontFamily, setHeaderAlignment, setWebsite, setReplyEmail, setAddress1, setTown, setPostcode, setOptOutText }} owner={owner} onSaveBranding={saveBranding} />
    </div>
  </div>
}

function TemplateGallery({ templates, library, owner, sender, sample, onChoose, onArchive }: { templates: LetterTemplate[]; library: AgencyTemplateLibraryItem[]; owner: boolean; sender: SenderProfile; sample: AgencyLead["company"]; onChoose: (key: string) => void; onArchive: (id: string, name: string) => void }) {
  const card = (item: LetterTemplate | AgencyTemplateLibraryItem, mine: boolean) => { const starter = mine ? library.find((candidate) => candidate.id === (item as LetterTemplate).sourceTemplateId) : undefined; return <article key={item.id} className="group flex min-w-0 flex-col overflow-hidden border-2 bg-background hover:shadow-[4px_4px_0_0_hsl(var(--foreground))]"><TemplateThumbnail item={item} sender={sender} sample={sample} /><div className="flex flex-1 flex-col p-4"><div className="flex items-start justify-between gap-2"><h3 className="font-black leading-tight">{item.name}</h3><div className="flex shrink-0 items-center gap-1"><Badge variant="outline">{mine ? "Draft" : "Starter"}</Badge>{mine && owner ? <button type="button" onClick={() => onArchive(item.id, item.name)} className="rounded p-1 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" aria-label={`Remove ${item.name}`} title="Remove template"><Trash2 className="size-4" /></button> : null}</div></div><p className="mt-2 line-clamp-2 text-sm text-muted-foreground">{"description" in item ? item.description : item.subject}</p><p className="mt-2 text-xs font-black capitalize">{item.layout?.design?.preset ?? "minimal"} design</p><div className="mt-4 grid gap-2"><Button type="button" className="w-full" variant={mine ? "default" : "outline"} onClick={() => onChoose(`${mine ? "mine" : "platform"}:${item.id}`)}>{mine ? "Edit template" : "Use template"}<ArrowRight className="ml-2 size-4" /></Button>{starter ? <Button type="button" className="w-full" variant="ghost" onClick={() => onChoose(`platform:${starter.id}`)}>Create refreshed copy</Button> : null}</div></div></article> }
  return <div className="space-y-6"><Card><CardHeader><CardTitle>Letter templates</CardTitle><CardDescription>Choose a starting point, then edit the letter directly on an A4 page.</CardDescription></CardHeader></Card>{templates.length ? <section><div className="mb-3"><h2 className="text-xl font-black">My templates</h2><p className="text-sm text-muted-foreground">Your saved workspace drafts.</p></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{templates.map((item) => card(item, true))}</div></section> : null}<section><div className="mb-3"><h2 className="text-xl font-black">Starting templates</h2><p className="text-sm text-muted-foreground">Platform originals stay unchanged.</p></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{library.map((item) => card(item, false))}</div></section></div>
}

function TemplateThumbnail({ item, sender, sample }: { item: LetterTemplate | AgencyTemplateLibraryItem; sender: SenderProfile; sample: AgencyLead["company"] }) { return <div className="h-64 overflow-hidden border-b-2 bg-[#ecebe7] p-3"><div className="relative mx-auto aspect-[210/297] h-full overflow-hidden bg-white shadow-sm"><div className="absolute left-0 top-0 h-[400%] w-[400%] origin-top-left scale-25"><LetterPreview subject={item.subject} bodyHtml={item.bodyHtml} ctaText={item.ctaText} ctaUrl={item.ctaUrl} signature={item.signature} sender={sender} serviceFocus={item.serviceFocus} layout={item.layout} sample={sample} /></div></div></div> }

const addableBlocks: Array<{ type: LetterBlockType; label: string; icon: React.ComponentType<{ className?: string }> }> = [{ type: "paragraph", label: "Text", icon: Type }, { type: "heading", label: "Heading", icon: Heading2 }, { type: "list", label: "List", icon: List }, { type: "image", label: "Image", icon: ImageIcon }, { type: "cta", label: "CTA", icon: ArrowRight }, { type: "qr", label: "QR", icon: QrCode }, { type: "divider", label: "Divider", icon: Minus }, { type: "spacer", label: "Space", icon: Space }]
function LetterToolbox({ onAdd }: { onAdd: (type: LetterBlockType) => void }) { return <aside className="order-2 flex gap-1 overflow-x-auto border-t-2 bg-foreground p-2 text-background lg:order-none lg:flex-col lg:border-r-2 lg:border-t-0" aria-label="Add letter content">{addableBlocks.map(({ type, label, icon: Icon }) => <button key={type} type="button" onClick={() => onAdd(type)} className="flex min-w-14 flex-col items-center gap-1 rounded px-2 py-2 text-[10px] font-bold hover:bg-background/15 focus-visible:outline focus-visible:outline-2"><Icon className="size-4" />{label}</button>)}</aside> }

function layoutToLegacy(layout: LetterLayout) { const heading = layout.blocks.find((item) => item.type === "heading")?.content?.trim() || "A quick idea for {{company_name}}"; const paragraphs = layout.blocks.filter((item) => item.type === "paragraph").map((item) => `<p>${escapeEditorHtml(item.content ?? "")}</p>`); const lists = layout.blocks.filter((item) => item.type === "list").map((item) => `<ul>${(item.items?.length ? item.items : (item.content ?? "").split("\n")).filter(Boolean).map((entry) => `<li>${escapeEditorHtml(entry)}</li>`).join("")}</ul>`); const cta = layout.blocks.find((item) => item.type === "cta"); const signature = layout.blocks.find((item) => item.type === "signature")?.content?.trim() || "Your team"; return { subject: heading, bodyHtml: [...paragraphs, ...lists].join("") || "<p>Hello {{company_name}},</p>", ctaText: cta?.content ?? "", ctaUrl: cta?.url ?? "", signature } }
function escapeEditorHtml(value: string) { return value.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]!) }

function LetterCanvas({ layout, sender, sample, serviceFocus, selectedId, onSelect, onChange, onOverflow }: { layout: LetterLayout; sender: SenderProfile; sample: { companyName: string; companyNumber: string; location?: string; incorporationDate?: string; sicCodes?: string[] }; serviceFocus: string[]; selectedId: string | null; onSelect: (id: string) => void; onChange: (layout: LetterLayout) => void; onOverflow: (overflowing: boolean) => void }) {
  const pageRef = React.useRef<HTMLDivElement>(null); const dragId = React.useRef<string | null>(null)
  const preset = layout.design?.preset ?? "minimal"
  const design = presetDesign(preset, sender)
  const editable = layout.blocks.filter((item) => !(requiredBlockTypes as readonly string[]).includes(item.type))
  React.useEffect(() => { const page = pageRef.current; if (!page) return; const check = () => onOverflow(page.scrollHeight > page.clientHeight + 4); check(); const observer = new ResizeObserver(check); observer.observe(page); return () => observer.disconnect() }, [layout, onOverflow])
  function update(id: string, changes: Partial<LetterBlock>) { onChange({ ...layout, blocks: layout.blocks.map((item) => item.id === id ? { ...item, ...changes } : item) }) }
  function move(id: string, direction: -1 | 1) { const index = layout.blocks.findIndex((item) => item.id === id); const target = index + direction; if (index < 0 || target < 0 || target >= layout.blocks.length || (requiredBlockTypes as readonly string[]).includes(layout.blocks[target].type)) return; const blocks = [...layout.blocks]; [blocks[index], blocks[target]] = [blocks[target], blocks[index]]; onChange({ ...layout, blocks }) }
  function drop(targetId: string) { const sourceId = dragId.current; if (!sourceId || sourceId === targetId) return; const blocks = [...layout.blocks]; const sourceIndex = blocks.findIndex((item) => item.id === sourceId); const targetIndex = blocks.findIndex((item) => item.id === targetId); if (sourceIndex < 0 || targetIndex < 0) return; const [source] = blocks.splice(sourceIndex, 1); blocks.splice(targetIndex, 0, source); onChange({ ...layout, blocks }); dragId.current = null }
  function editableBlock(item: LetterBlock, compact = false) { return <div key={item.id} draggable onDragStart={() => { dragId.current = item.id }} onDragOver={(event) => event.preventDefault()} onDrop={() => drop(item.id)} onClick={() => onSelect(item.id)} className={`group relative rounded border-2 border-transparent transition-colors hover:border-dashed hover:border-muted-foreground/40 ${compact ? "min-w-0 p-2" : "-mx-3 px-3 py-1"} ${selectedId === item.id ? "border-solid border-foreground bg-background/70" : ""}`}>
    <div className={`absolute top-1 z-10 hidden gap-0.5 rounded bg-background shadow-sm group-hover:flex group-focus-within:flex ${compact ? "left-1" : "-left-9 flex-col"}`}><button type="button" className="cursor-grab p-1" aria-label="Drag to reorder"><GripVertical className="size-4" /></button><button type="button" onClick={(event) => { event.stopPropagation(); move(item.id, -1) }} className="p-1" aria-label="Move up"><ArrowUp className="size-3" /></button><button type="button" onClick={(event) => { event.stopPropagation(); move(item.id, 1) }} className="p-1" aria-label="Move down"><ArrowDown className="size-3" /></button></div>
    <CanvasBlock item={item} sender={sender} serviceFocus={serviceFocus} selected={selectedId === item.id} variables={{ company_name: sample.companyName, company_number: sample.companyNumber, incorporation_date: sample.incorporationDate ?? "Recently incorporated", sic_codes: sample.sicCodes?.join(", ") ?? "", location: sample.location ?? "London", registered_office_address: `10 Example Street, ${sample.location ?? "London"}, UK`, agency_name: sender.agencyName, service_focus: serviceFocus.join(", "), opt_out_reference: "PREVIEW-1234" }} onChange={(changes) => update(item.id, changes)} />
    <button type="button" onClick={(event) => { event.stopPropagation(); onChange({ ...layout, blocks: layout.blocks.filter((candidate) => candidate.id !== item.id) }) }} className={`absolute top-1 z-10 hidden rounded bg-background p-1 text-destructive shadow-sm group-hover:block group-focus-within:block ${compact ? "right-1" : "-right-8"}`} aria-label="Delete block"><Trash2 className="size-4" /></button>
  </div> }
  const logo = normalizeExternalUrl(sender.logoUrl)
  return <div className="aspect-[210/297] w-full border-2 bg-white shadow-[7px_7px_0_0_hsl(var(--foreground))]"><div ref={pageRef} className="relative h-full overflow-hidden" style={{ ...design.page, color: sender.textColor }}><PresetDecorations preset={preset} accent={normalizeAccentColor(sender.accentColor)} primary={normalizeAccentColor(sender.primaryColor)} />
    <div className="mb-6" style={{ textAlign: sender.headerAlignment }}>{logo ? <img src={logo} alt={sender.agencyName} className={`max-h-12 max-w-44 object-contain ${sender.headerAlignment === "center" ? "mx-auto" : sender.headerAlignment === "right" ? "ml-auto" : ""}`} /> : <strong>{sender.agencyName}</strong>}</div>
    <div className="mb-6 text-sm"><strong>To:</strong><br />{sample.companyName}<br />10 Example Street, {sample.location ?? "London"}, UK</div>
    {editable.map((item, index) => { const next = editable[index + 1]; if (item.type === "qr" && editable[index - 1]?.type === "cta") return null; if (item.type === "cta" && next?.type === "qr") return <div key={`${item.id}-${next.id}`} className="my-4 grid grid-cols-[minmax(0,1fr)_150px] items-center gap-4 rounded border p-3" style={{ borderColor: normalizeAccentColor(sender.primaryColor), backgroundColor: `${normalizeAccentColor(sender.accentColor)}12` }}>{editableBlock(item, true)}{editableBlock(next, true)}</div>; return editableBlock(item) })}
    <footer className="mt-3 border-t pt-3 text-[10px] text-muted-foreground">{sender.agencyName}{sender.website ? ` · ${sender.website}` : ""} · {sender.replyEmail} · {sender.optOutText} Reference: PREVIEW-1234</footer>
  </div></div>
}

function PresetDecorations({ preset, accent, primary }: { preset: NonNullable<LetterLayout["design"]>["preset"]; accent: string; primary: string }) { const safePreset = preset === "modern" || preset === "editorial" ? preset : "minimal"; if (safePreset === "modern") return <><span className="pointer-events-none absolute inset-x-0 top-0 z-0 h-[1.2%]" style={{ background: accent }} /><span className="pointer-events-none absolute inset-x-[8%] bottom-[4%] z-0 h-px" style={{ background: primary }} /></>; if (safePreset === "editorial") return <><span className="pointer-events-none absolute inset-x-[8%] top-[9%] z-0 h-px" style={{ background: accent }} /><span className="pointer-events-none absolute inset-x-[8%] bottom-[4%] z-0 h-px" style={{ background: accent }} /></>; return <><span className="pointer-events-none absolute left-0 top-0 z-0 h-full w-[1%]" style={{ background: accent }} /><span className="pointer-events-none absolute right-[8%] top-[5%] z-0 h-px w-[22%]" style={{ background: primary }} /></> }

function presetDesign(preset: NonNullable<LetterLayout["design"]>["preset"], sender: SenderProfile): { page: React.CSSProperties } {
  const accent = normalizeAccentColor(sender.accentColor); const primary = normalizeAccentColor(sender.primaryColor)
  if (preset === "modern") return { page: { padding: "8% 9%", fontFamily: "Helvetica, Arial, sans-serif" } }
  if (preset === "editorial") return { page: { padding: "11% 9% 8%", fontFamily: "Georgia, serif" } }
  return { page: { padding: "8% 9%", fontFamily: "Arial, sans-serif" } }
}

function CanvasBlock({ item, sender, serviceFocus, selected, variables, onChange }: { item: LetterBlock; sender: SenderProfile; serviceFocus: string[]; selected: boolean; variables: Record<string, string>; onChange: (changes: Partial<LetterBlock>) => void }) {
  const fieldClass = "w-full resize-none overflow-hidden border-0 bg-transparent p-0 outline-none placeholder:text-muted-foreground/60"
  const raw = item.content ?? ""; const personalised = /\{\{\s*[a-z_]+\s*\}\}/i.test(raw)
  if (item.type === "heading") return personalised && !selected ? <h2 className="text-xl font-black" style={{ color: sender.primaryColor, textAlign: item.align }}>{replaceMergePreview(raw, variables)}</h2> : <textarea rows={Math.max(1, raw.split("\n").length)} value={raw} onChange={(event) => onChange({ content: event.target.value })} className={`${fieldClass} text-xl font-black`} style={{ color: sender.primaryColor, textAlign: item.align }} aria-label="Letter heading" />
  if (item.type === "paragraph") return personalised && !selected ? <p className="text-sm leading-6" style={{ textAlign: item.align }}>{replaceMergePreview(raw, variables)}</p> : <textarea rows={Math.max(2, Math.ceil((raw.length || 1) / 72))} value={raw} onChange={(event) => onChange({ content: event.target.value })} className={`${fieldClass} text-sm leading-6`} style={{ textAlign: item.align }} aria-label="Letter paragraph" />
  if (item.type === "list") { const dynamic = item.content?.trim() === "{{service_focus}}" || item.items?.some((entry) => entry.trim() === "{{service_focus}}"); return dynamic ? <ul className="ml-5 list-disc text-sm leading-6">{(serviceFocus.length ? serviceFocus : ["Add services in Personalise"]).map((service) => <li key={service}>{service}</li>)}</ul> : <div className="flex gap-2 text-sm"><span aria-hidden="true">•</span><textarea rows={Math.max(2, (item.content ?? "").split("\n").length)} value={item.content ?? ""} onChange={(event) => onChange({ content: event.target.value, items: event.target.value.split("\n") })} className={`${fieldClass} leading-6`} aria-label="Letter list, one item per line" /></div> }
  if (item.type === "image") { const url = normalizeExternalUrl(item.url); return url ? <img src={url} alt={item.alt ?? "Letter artwork"} className="mx-auto my-2 max-h-48 max-w-full object-contain" /> : <div className="my-2 flex h-24 items-center justify-center border-2 border-dashed text-xs text-muted-foreground"><ImageIcon className="mr-2 size-4" />Select this block to upload an image</div> }
  if (item.type === "cta") return <div className="flex h-full items-center" style={{ textAlign: item.align }}><input value={item.content ?? ""} onChange={(event) => onChange({ content: event.target.value })} className="w-full border-0 px-4 py-3 text-center text-xs font-bold text-black outline-none" style={{ backgroundColor: normalizeAccentColor(sender.accentColor) }} aria-label="Call to action text" /></div>
  if (item.type === "qr") { const url = normalizeExternalUrl(item.url); const qrClass = item.size === "large" ? "size-24" : item.size === "medium" ? "size-20" : "size-16"; return <div className="text-center">{url ? <><img src={qrSvgDataUrl(url, normalizeAccentColor(sender.primaryColor))} alt="QR code preview" className={`mx-auto ${qrClass}`} />{item.content ? <p className="mt-1 text-[9px] leading-tight">{item.content}</p> : null}</> : <div className="mx-auto inline-flex size-20 items-center justify-center border-2 border-dashed"><QrCode className="size-7" /></div>}</div> }
  if (item.type === "signature") return personalised && !selected ? <p className="my-1 font-bold" style={{ textAlign: item.align }}>{replaceMergePreview(raw, variables)}</p> : <input value={raw} onChange={(event) => onChange({ content: event.target.value })} className={`${fieldClass} my-1 font-bold`} style={{ textAlign: item.align }} aria-label="Signature" />
  if (item.type === "divider") return <hr className="my-3" style={{ borderColor: sender.primaryColor }} />
  if (item.type === "spacer") return <div className="h-6" aria-label="Spacer" />
  return null
}

type BrandSetters = { setAgencyName: React.Dispatch<React.SetStateAction<string>>; setLogoUrl: React.Dispatch<React.SetStateAction<string>>; setAccentColor: React.Dispatch<React.SetStateAction<string>>; setPrimaryColor: React.Dispatch<React.SetStateAction<string>>; setTextColor: React.Dispatch<React.SetStateAction<string>>; setFontFamily: React.Dispatch<React.SetStateAction<string>>; setHeaderAlignment: React.Dispatch<React.SetStateAction<"left" | "center" | "right">>; setWebsite: React.Dispatch<React.SetStateAction<string>>; setReplyEmail: React.Dispatch<React.SetStateAction<string>>; setAddress1: React.Dispatch<React.SetStateAction<string>>; setTown: React.Dispatch<React.SetStateAction<string>>; setPostcode: React.Dispatch<React.SetStateAction<string>>; setOptOutText: React.Dispatch<React.SetStateAction<string>> }
function LetterInspector({ panel, setPanel, selected, onBlockChange, serviceFocus, setServiceFocus, customService, setCustomService, addCustomService, sender, setters, owner, onSaveBranding }: { panel: "content" | "brand" | "personalise"; setPanel: (panel: "content" | "brand" | "personalise") => void; selected?: LetterBlock; onBlockChange: (changes: Partial<LetterBlock>) => void; serviceFocus: string[]; setServiceFocus: (services: string[]) => void; customService: string; setCustomService: (value: string) => void; addCustomService: () => void; sender: SenderProfile; setters: BrandSetters; owner: boolean; onSaveBranding: () => void }) {
  return <aside className="order-3 min-w-0 border-t-2 bg-card lg:border-l-2 lg:border-t-0"><div className="grid grid-cols-3 border-b-2 text-xs font-bold">{(["content", "brand", "personalise"] as const).map((item) => <button type="button" key={item} onClick={() => setPanel(item)} className={`px-2 py-3 capitalize ${panel === item ? "bg-[hsl(var(--chart-2))]" : "hover:bg-muted"}`}>{item}</button>)}</div><div className="max-h-[760px] space-y-4 overflow-y-auto p-4">
    {panel === "content" ? selected ? <><div><p className="text-xs font-black uppercase text-muted-foreground">Selected element</p><h3 className="mt-1 text-lg font-black capitalize">{selected.type}</h3>{/\{\{\s*[a-z_]+\s*\}\}/i.test(selected.content ?? "") ? <p className="mt-2 text-xs text-muted-foreground">Personalised fields show sample company details on the letter and are replaced automatically for every recipient.</p> : null}</div>{["cta", "qr"].includes(selected.type) ? <label className="text-sm font-bold">Destination URL<Input value={selected.url ?? ""} onChange={(event) => onBlockChange({ url: event.target.value })} className="mt-1" placeholder="https://…" /></label> : null}{selected.type === "qr" ? <><label className="text-sm font-bold">Printed label (optional)<Input value={selected.content ?? ""} onChange={(event) => onBlockChange({ content: event.target.value })} className="mt-1" placeholder="Scan to choose a time" /></label><label className="text-sm font-bold">QR size<select value={selected.size ?? "medium"} onChange={(event) => onBlockChange({ size: event.target.value as "small" | "medium" | "large" })} className="mt-1 h-10 w-full border-2 bg-background px-3"><option value="small">Small</option><option value="medium">Medium</option><option value="large">Large</option></select></label>{normalizeExternalUrl(selected.url) ? <a href={normalizeExternalUrl(selected.url)!} target="_blank" rel="noreferrer" className="text-sm font-bold underline">Test destination ↗</a> : <p className="text-xs font-medium text-destructive">Use a valid HTTPS destination before finishing.</p>}</> : null}{selected.type === "image" ? <><AssetUpload onChange={(url) => onBlockChange({ url })} /><details><summary className="cursor-pointer text-xs font-bold">Use image URL</summary><Input value={selected.url ?? ""} onChange={(event) => onBlockChange({ url: event.target.value })} className="mt-2" placeholder="https://…" /></details><label className="text-sm font-bold">Alt text<Input value={selected.alt ?? ""} onChange={(event) => onBlockChange({ alt: event.target.value })} className="mt-1" /></label></> : null}{!["divider", "spacer", "image"].includes(selected.type) ? <label className="text-sm font-bold">Alignment<select value={selected.align ?? "left"} onChange={(event) => onBlockChange({ align: event.target.value as "left" | "center" | "right" })} className="mt-1 h-10 w-full border-2 bg-background px-3"><option value="left">Left</option><option value="center">Centre</option><option value="right">Right</option></select></label> : null}</> : <div className="border-2 border-dashed p-4 text-sm text-muted-foreground">Select an element on the letter to edit its settings.</div> : null}
    {panel === "brand" ? <><label className="text-sm font-bold">Agency name<Input value={sender.agencyName} onChange={(event) => setters.setAgencyName(event.target.value)} className="mt-1" /></label><LogoUpload value={sender.logoUrl ?? ""} onChange={setters.setLogoUrl} /><div className="grid grid-cols-3 gap-2"><Colour label="Accent" value={sender.accentColor ?? DEFAULT_ACCENT_COLOR} onChange={setters.setAccentColor} /><Colour label="Heading" value={sender.primaryColor ?? "#111827"} onChange={setters.setPrimaryColor} /><Colour label="Text" value={sender.textColor ?? "#111827"} onChange={setters.setTextColor} /></div><label className="text-sm font-bold">Font<select value={sender.fontFamily} onChange={(event) => setters.setFontFamily(event.target.value)} className="mt-1 h-10 w-full border-2 bg-background px-3"><option>Arial</option><option>Georgia</option><option>Helvetica</option><option>Times New Roman</option></select></label><label className="text-sm font-bold">Header alignment<select value={sender.headerAlignment} onChange={(event) => setters.setHeaderAlignment(event.target.value as "left" | "center" | "right")} className="mt-1 h-10 w-full border-2 bg-background px-3"><option value="left">Left</option><option value="center">Centre</option><option value="right">Right</option></select></label><Input value={sender.website ?? ""} onChange={(event) => setters.setWebsite(event.target.value)} placeholder="Website" /><Input value={sender.replyEmail} onChange={(event) => setters.setReplyEmail(event.target.value)} placeholder="Reply email" /><Input value={sender.address.address1} onChange={(event) => setters.setAddress1(event.target.value)} placeholder="Sender address" /><div className="grid grid-cols-2 gap-2"><Input value={sender.address.town} onChange={(event) => setters.setTown(event.target.value)} placeholder="Town" /><Input value={sender.address.postcode} onChange={(event) => setters.setPostcode(event.target.value)} placeholder="Postcode" /></div><Input value={sender.optOutText} onChange={(event) => setters.setOptOutText(event.target.value)} placeholder="Opt-out footer" /><Button type="button" className="w-full" onClick={onSaveBranding} disabled={!owner || !sender.agencyName.trim() || !sender.replyEmail.trim() || !sender.address.address1.trim() || !sender.address.town.trim() || !sender.address.postcode.trim()}>Save brand settings</Button><p className="text-xs text-muted-foreground">Brand settings apply to every workspace letter.</p></> : null}
    {panel === "personalise" ? <><div><h3 className="font-black">Personalised details</h3><p className="mt-1 text-xs text-muted-foreground">These fields become the recipient&apos;s real company details before printing.</p></div><div className="flex flex-wrap gap-1">{mergeFields.map((field) => <button type="button" key={field} disabled={!selected || !["heading", "paragraph", "list", "cta", "signature"].includes(selected.type)} onClick={() => onBlockChange({ content: `${selected?.content ?? ""}{{${field}}}` })} className="border bg-background px-2 py-1 text-[11px] font-bold disabled:opacity-40">+ {mergeFieldLabels[field]}</button>)}</div><div className="border-t-2 pt-4"><p className="text-sm font-black">Services to mention</p><div className="mt-2 flex flex-wrap gap-1">{serviceFocus.map((service) => <button type="button" key={service} onClick={() => setServiceFocus(serviceFocus.filter((item) => item !== service))} className="border-2 bg-[hsl(var(--chart-2))] px-2 py-1 text-xs font-bold">{service} ×</button>)}</div><div className="mt-2 flex gap-1"><Input value={customService} onChange={(event) => setCustomService(event.target.value)} placeholder="Add service" /><Button type="button" size="sm" variant="outline" onClick={addCustomService}>Add</Button></div></div></> : null}
  </div></aside>
}
function Colour({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { return <label className="text-[10px] font-bold">{label}<Input type="color" value={value} onChange={(event) => onChange(event.target.value)} className="mt-1 p-1" /></label> }
function AssetUpload({ onChange }: { onChange: (url: string) => void }) { const [busy, setBusy] = React.useState(false); async function upload(file?: File) { if (!file) return; setBusy(true); try { const body = new FormData(); body.append("file", file); const response = await fetch("/api/app/assets", { method: "POST", body }); const result = await response.json(); if (!response.ok) throw new Error(result.error ?? "Upload failed."); onChange(result.url) } finally { setBusy(false) } } return <label className="block border-2 border-dashed p-3 text-center text-xs font-bold"><ImagePlus className="mx-auto mb-2 size-5" />{busy ? "Uploading…" : "Upload image"}<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" className="sr-only" disabled={busy} onChange={(event) => upload(event.target.files?.[0])} /></label> }

function LogoUpload({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const [busy, setBusy] = React.useState(false)
  async function upload(file?: File) { if (!file) return; setBusy(true); try { const body = new FormData(); body.append("file", file); const response = await fetch("/api/app/assets", { method: "POST", body }); const result = await response.json(); if (!response.ok) throw new Error(result.error ?? "Upload failed."); onChange(result.url) } finally { setBusy(false) } }
  return <label className="text-sm font-bold">Logo<Input value={value} onChange={(event) => onChange(event.target.value)} className="mt-1" placeholder="Logo URL or upload below" /><input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" disabled={busy} onChange={(event) => upload(event.target.files?.[0])} className="mt-2 block w-full text-xs" />{busy ? <span className="text-xs text-muted-foreground">Uploading…</span> : null}</label>
}
function RichLetterEditor({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const editorRef = React.useRef<HTMLDivElement>(null)
  const [imageUrl, setImageUrl] = React.useState("")
  React.useEffect(() => { if (editorRef.current && editorRef.current.innerHTML !== value) editorRef.current.innerHTML = value }, [value])
  function command(name: string, argument?: string) { editorRef.current?.focus(); document.execCommand(name, false, argument); onChange(editorRef.current?.innerHTML ?? "") }
  function insertMerge(field: string) { command("insertText", `{{${field}}}`) }
  function insertImage() { const url = imageUrl.trim(); if (!/^https?:\/\//i.test(url)) return; editorRef.current?.focus(); const image = `<p><img src="${url.replace(/"/g, "&quot;")}" alt="" style="max-width:100%" /></p>`; document.execCommand("insertHTML", false, image); onChange(editorRef.current?.innerHTML ?? `${value}${image}`); setImageUrl("") }
  const basicControls = [{ label: "Bold", shortLabel: "B", icon: Bold, action: () => command("bold") }, { label: "Italic", shortLabel: "I", icon: Italic, action: () => command("italic") }, { label: "Heading", shortLabel: "H2", action: () => command("formatBlock", "h2") }, { label: "Bullet list", shortLabel: "•", icon: List, action: () => command("insertUnorderedList") }, { label: "Numbered list", shortLabel: "1.", icon: ListOrdered, action: () => command("insertOrderedList") }]
  const advancedControls = [{ label: "Underline", icon: Underline, action: () => command("underline") }, { label: "Add link", icon: LinkIcon, action: () => command("createLink", window.prompt("Link URL") ?? "") }, { label: "Undo", icon: Undo2, action: () => command("undo") }, { label: "Redo", icon: Redo2, action: () => command("redo") }]
  const controlButton = ({ label, shortLabel, icon: Icon, action }: { label: string; shortLabel?: string; icon?: React.ComponentType<{ className?: string }>; action: () => void }) => <button type="button" key={label} onMouseDown={(event) => event.preventDefault()} onClick={action} className="flex size-8 items-center justify-center border-2 bg-background text-xs font-black hover:bg-[hsl(var(--chart-2))]" aria-label={label} title={label}>{Icon ? <Icon className="size-4" /> : shortLabel}</button>
  return <div className="min-w-0 border-2 bg-background">
    <div className="flex flex-wrap items-center gap-1 border-b-2 bg-muted p-2" aria-label="Basic text formatting">{basicControls.map(controlButton)}</div>
    <div ref={editorRef} role="textbox" aria-label="Main letter message" aria-multiline="true" contentEditable suppressContentEditableWarning onInput={() => onChange(editorRef.current?.innerHTML ?? "")} className="min-h-56 w-full overflow-x-auto p-4 outline-none [&_h2]:mb-2 [&_h2]:text-xl [&_h2]:font-black [&_img]:my-3 [&_img]:max-w-full [&_ol]:ml-5 [&_ol]:list-decimal [&_p]:mb-2 [&_ul]:ml-5 [&_ul]:list-disc" data-placeholder="Write your letter here..." />
    <details className="border-t-2 bg-muted">
      <summary className="cursor-pointer px-3 py-2 text-sm font-black focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px]">Advanced editing</summary>
      <div className="space-y-3 border-t-2 p-3">
        <div><p className="mb-2 text-xs font-bold">More formatting</p><div className="flex flex-wrap gap-1">{advancedControls.map(controlButton)}</div></div>
        <div><label className="text-xs font-bold" htmlFor="campaign-letter-image">Add an image from a URL</label><div className="mt-1 flex min-w-0 items-center gap-1"><ImagePlus className="size-4 shrink-0" /><Input id="campaign-letter-image" value={imageUrl} onChange={(event) => setImageUrl(event.target.value)} className="h-8 min-w-0 flex-1 border-2 bg-background text-xs" placeholder="https://example.com/image.png" /><button type="button" onMouseDown={(event) => event.preventDefault()} onClick={insertImage} className="flex h-8 shrink-0 items-center gap-1 border-2 bg-background px-2 text-xs font-bold hover:bg-[hsl(var(--chart-2))]">Add</button></div></div>
        <div><p className="text-xs font-bold">Personalised details</p><p className="my-1 text-xs text-muted-foreground">Insert a field where you want it to appear. It will be replaced with the recipient&apos;s real company details before printing.</p><div className="flex flex-wrap gap-1">{mergeFields.map((field) => <button type="button" key={field} onMouseDown={(event) => event.preventDefault()} onClick={() => insertMerge(field)} className="border bg-background px-2 py-1 text-[11px] font-bold hover:bg-[hsl(var(--chart-2))]">+ {mergeFieldLabels[field]}</button>)}</div></div>
      </div>
    </details>
  </div>
}

type LetterPreviewProps = { subject: string; bodyHtml: string; ctaText?: string; ctaUrl?: string; signature: string; sender?: SenderProfile; serviceFocus?: string[]; layout?: LetterLayout; sample?: { companyName: string; companyNumber: string; incorporationDate?: string; location?: string; sicCodes?: string[] } }

function ScaledLetterPreview(props: LetterPreviewProps) {
  const frameRef = React.useRef<HTMLDivElement>(null)
  const [scale, setScale] = React.useState(0.45)
  React.useLayoutEffect(() => {
    const frame = frameRef.current
    if (!frame) return
    const update = () => setScale(frame.clientWidth / 794)
    update()
    const observer = new ResizeObserver(update)
    observer.observe(frame)
    return () => observer.disconnect()
  }, [])
  return <div ref={frameRef} className="relative aspect-[210/297] w-full overflow-hidden border-2 bg-background shadow-[5px_5px_0_0_hsl(var(--foreground))]"><div className="absolute left-0 top-0 h-[1123px] w-[794px] origin-top-left" style={{ transform: `scale(${scale})` }}><LetterPreview {...props} /></div></div>
}

function LetterPreview({ subject, bodyHtml, ctaText, ctaUrl, signature, sender, serviceFocus = [], layout, sample = DEFAULT_LETTER_SAMPLE }: LetterPreviewProps) {
  const vars: Record<string, string> = { company_name: sample.companyName, company_number: sample.companyNumber, incorporation_date: sample.incorporationDate ?? "23 July 2026", location: sample.location ?? "London", sic_codes: (sample.sicCodes ?? []).join(", "), registered_office_address: "10 Example Street, London, UK", agency_name: sender?.agencyName ?? "Your agency", service_focus: serviceFocus.join(", "), opt_out_reference: "PREVIEW-1234" }
  const replace = (value: string) => value.replace(/\{\{\s*([a-z_]+)\s*\}\}/gi, (_, key) => vars[key] ?? "")
  const accent = normalizeAccentColor(sender?.accentColor)
  const logoUrl = normalizeExternalUrl(sender?.logoUrl)
  const website = normalizeExternalUrl(sender?.website)
  const [logoFailed, setLogoFailed] = React.useState(false)
  React.useEffect(() => setLogoFailed(false), [logoUrl])
  const safeBody = replace(bodyHtml || "Hello {{company_name}},").replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "").replace(/\son\w+=("[^"]*"|'[^']*'|[^\s>]+)/gi, "").replace(/javascript:/gi, "")
  const safeCtaUrl = normalizeExternalUrl(ctaUrl)
  if (layout) {
    const renderBlock = (item: LetterBlock, compact = false) => {
      const content = replace(item.content ?? "")
      const align = item.align ?? "left"
      if (item.type === "brand") return <div className="mb-6" style={{ textAlign: sender?.headerAlignment ?? align }}>{logoUrl && !logoFailed ? <img src={logoUrl} alt={sender?.agencyName ?? "Your agency"} onError={() => setLogoFailed(true)} className={`max-h-12 max-w-44 object-contain ${align === "center" ? "mx-auto" : align === "right" ? "ml-auto" : ""}`} /> : <strong>{sender?.agencyName ?? "Your agency"}</strong>}</div>
      if (item.type === "recipient") return <div className="mb-6 text-sm"><strong>To:</strong><br />{sample.companyName}<br />10 Example Street, {sample.location ?? "London"}, UK</div>
      if (item.type === "heading") return <h2 className="mb-4 text-xl font-black" style={{ color: sender?.primaryColor, textAlign: align }}>{content}</h2>
      if (item.type === "paragraph") return <p className="mb-3 text-sm leading-6" style={{ textAlign: align }}>{content}</p>
      if (item.type === "list") { const entries = item.content?.trim() === "{{service_focus}}" || item.items?.some((entry) => entry.trim() === "{{service_focus}}") ? serviceFocus : (item.items?.length ? item.items : (item.content ?? "").split("\n")); return <ul className="mb-4 ml-5 list-disc text-sm">{entries.filter(Boolean).map((entry, index) => <li key={`${item.id}-${index}`}>{replace(entry)}</li>)}</ul> }
      if (item.type === "image") { const url = normalizeExternalUrl(item.url); return url ? <div style={{ textAlign: align }}><img src={url} alt={item.alt ?? "Letter artwork"} className="my-4 inline-block max-h-52 max-w-full object-contain" /></div> : null }
      if (item.type === "cta") { const url = normalizeExternalUrl(item.url); return url ? <p className={compact ? "my-0" : "my-4"} style={{ textAlign: align }}><a href={url} target="_blank" rel="noreferrer" className="block px-4 py-3 text-center text-xs font-bold text-black" style={{ backgroundColor: accent }}>{content || "Learn more"}</a></p> : null }
      if (item.type === "qr") { const url = normalizeExternalUrl(item.url); return url ? <div className={compact ? "my-0 text-center" : "my-4 text-center"}><img src={qrSvgDataUrl(url)} alt="QR code preview" className="inline-block size-20" />{item.content ? <p className="text-[9px] leading-tight">{item.content}</p> : null}</div> : null }
      if (item.type === "signature") return <p className="my-5 font-bold" style={{ textAlign: align }}>{content || signature}</p>
      if (item.type === "divider") return <hr className="my-4" style={{ borderColor: sender?.primaryColor }} />
      if (item.type === "spacer") return <div className="h-6" />
      if (item.type === "footer") return <small className="mt-5 block border-t pt-3 text-muted-foreground">{sender?.agencyName ?? "Your agency"}{website ? ` · ${website}` : ""} · {sender?.replyEmail ?? "reply@agency.com"} · {sender?.optOutText ?? "To opt out, use this reference."} Reference: PREVIEW-1234</small>
      return null
    }
    const rendered: React.ReactNode[] = []
    for (let index = 0; index < layout.blocks.length; index += 1) { const item = layout.blocks[index]; const next = layout.blocks[index + 1]; if (item.type === "cta" && next?.type === "qr") { rendered.push(<div key={`${item.id}-${next.id}`} className="my-4 grid grid-cols-[minmax(0,1fr)_120px] items-center gap-4 border p-3" style={{ borderColor: sender?.primaryColor, backgroundColor: `${accent}12` }}><div>{renderBlock(item, true)}</div><div>{renderBlock(next, true)}</div></div>); index += 1 } else rendered.push(<React.Fragment key={item.id}>{renderBlock(item)}</React.Fragment>) }
    const preset = layout.design?.preset === "modern" || layout.design?.preset === "editorial" ? layout.design.preset : "minimal"
    const pageStyle: React.CSSProperties = preset === "editorial"
      ? { padding: "11% 9% 8%", fontFamily: "Georgia, serif" }
      : { padding: "8% 9%", fontFamily: preset === "modern" ? "Helvetica, Arial, sans-serif" : "Arial, sans-serif" }
    return <article className="a4-letter-preview relative min-h-full overflow-hidden bg-background" style={{ ...pageStyle, color: sender?.textColor }}><PresetDecorations preset={preset} accent={accent} primary={normalizeAccentColor(sender?.primaryColor)} /><div className="relative z-10">{rendered}</div></article>
  }
  return <article className="a4-letter-preview min-h-full bg-background p-6 sm:p-8" style={{ borderTop: `8px solid ${accent}` }}>{logoUrl && !logoFailed ? <img src={logoUrl} alt={sender?.agencyName ?? "Your agency"} onError={() => setLogoFailed(true)} className="mb-5 max-h-10 max-w-40 object-contain" /> : <p className="mb-5 font-black">{sender?.agencyName ?? "Your agency"}</p>}<p className="letter-subject font-black">{replace(subject || "A quick idea for {{company_name}}")}</p><div className="letter-copy mt-5" dangerouslySetInnerHTML={{ __html: safeBody }} />{ctaText && safeCtaUrl ? <a href={safeCtaUrl} target="_blank" rel="noreferrer" className="mt-3 inline-block border-2 px-3 py-2 text-xs font-bold" style={{ backgroundColor: accent }}>{replace(ctaText)}</a> : null}<p className="mt-6 font-bold">{replace(signature || "Your team")}</p><hr className="my-4 border-foreground" /><small className="text-muted-foreground">{sender?.agencyName ?? "Your agency"}{website ? ` · ${website}` : ""} · {sender?.replyEmail ?? "reply@agency.com"} · {sender?.optOutText ?? "To opt out, use reference PREVIEW-1234."} Reference: PREVIEW-1234</small></article>
}
